  _recipeCard(r,custom=false){const m=r.match||{};const coverage=Number.isFinite(Number(m.pantryCoverage))?Math.round(Number(m.pantryCoverage)*100):null;const ingredients=(r.ingredients||[]).slice(0,6).map(x=>this._ingredientText(x)).filter(Boolean);const canSend=!custom&&r.sendable!==false&&this._entry()?.canAcceptRecipe&&m.safe!==false;const reason=m.safe===false?this._t("blocked"):(!this._entry()?.connected?this._t("disconnected"):(this._entry()?.loadedRecipe?this._t("loaded"):""));const source=custom?(r.source||"manual"):"SEB";const lang=this._recipeLanguage(r);const serving=this._servings(r);return `<article class="card recipe" data-recipe="${this._escape(r.id||r.displayVariantId||r.searchVariantId||"")}">${this._mediaHtml(r)}<h3>${this._escape(this._clean(r.title||r.searchVariantId||"Recipe"))}</h3><div class="chips"><span class="chip">${this._escape(source)}</span>${serving!==null?`<span class="chip">${this._escape(this._t("servings"))}: ${this._escape(serving)}</span>`:""}${lang&&lang!==this._langCode()?`<span class="chip warn">${this._escape(this._t("sourceLanguage"))}: ${this._escape(lang.toUpperCase())}</span>`:""}${m.dietary?.pescatarian&&!m.dietary?.vegetarian?`<span class="chip">🐟 ${this._t("pescatarian")}</span>`:""}${m.dietary?.vegetarian?`<span class="chip">🌱 ${this._t("vegetarian")}</span>`:""}${m.dietary?.vegan?`<span class="chip">🌿 ${this._t("vegan")}</span>`:""}${coverage!==null?`<span class="chip">${this._t("coverage")}: ${coverage}%</span>`:""}${m.habitHits?.length?`<span class="chip">♥ ${this._t("habitMatch")}</span>`:""}${m.safe===false?`<span class="chip bad">${this._t("blocked")}</span>`:""}</div>${ingredients.length?`<div class="ingredients"><strong>${this._t("ingredients")}:</strong> ${ingredients.map(x=>this._escape(x)).join(", ")}</div>`:""}${m.missingIngredients?.length?`<div class="ingredients missing"><strong>${this._t("missing")}:</strong> ${m.missingIngredients.slice(0,5).map(x=>this._escape(this._clean(x))).join(", ")}</div>`:""}<div class="actions"><button class="btn secondary" data-action="open">${this._t(custom?"cookAlong":"steps")}</button>${custom?`<button class="btn danger" data-action="delete">${this._t("delete")}</button>`:`<button class="btn" data-action="send" ${canSend?"":`disabled title="${this._escape(reason)}"`}>${this._t("send")}</button>`}</div></article>`;}
  _bindCards(container,items,custom=false){container.querySelectorAll(".recipe").forEach((card,i)=>{const r=items[i];const img=card.querySelector("img.cover");img?.addEventListener("error",()=>img.remove());card.querySelector('[data-action="open"]')?.addEventListener("click",()=>custom?this._openLocal(r):this._openOfficial(r));card.querySelector('[data-action="send"]')?.addEventListener("click",()=>this._send(r));card.querySelector('[data-action="delete"]')?.addEventListener("click",()=>this._deleteRecipe(r));});}
