// cook4me-panel-v15.js
(() => {

const BasePanel = customElements.get("cook4me-recipe-hub-panel-v14");

const TEXT = {
  en:{
    recommendQuery:"Recipe filter",recommendQueryPlaceholder:"e.g. risotto",dietFilter:"Diet filter",profileDiet:"Profile diet",
  },
  de:{
    recommendQuery:"Rezeptfilter",recommendQueryPlaceholder:"z. B. Risotto",dietFilter:"Ernährungsfilter",profileDiet:"Profil-Ernährung",
  },
  el:{
    recommendQuery:"Φίλτρο συνταγής",recommendQueryPlaceholder:"π.χ. ριζότο",dietFilter:"Φίλτρο διατροφής",profileDiet:"Διατροφή προφίλ",
  },
};

class Cook4MeRecipeHubPanelV15 extends BasePanel {
  constructor(){
    super();
    this._recommendQuery="";
    this._recommendDiet="profile";
  }

  _t(key){return TEXT[this._langCode()]?.[key]||TEXT.en[key]||super._t(key);}

  _recommendDietOptions(){
    const profileDiet=String(this._entry()?.profile?.diet||"omnivore");
    const options=[
      ["profile",`${this._t("profileDiet")} (${this._t(profileDiet)})`],
      ["omnivore",this._t("omnivore")],
      ["pescatarian",this._t("pescatarian")],
      ["vegetarian",this._t("vegetarian")],
      ["vegan",this._t("vegan")],
    ];
    return options.map(([value,label])=>`<option value="${this._escape(value)}" ${value===this._recommendDiet?"selected":""}>${this._escape(label)}</option>`).join("");
  }

  _renderRecommend(c){
    const locale=this._localeControlsHtml();
    c.innerHTML=`<section class="card">
      ${locale}
      <div class="toolbar" style="align-items:end">
        <div class="field" style="min-width:220px"><label>${this._escape(this._t("dietFilter"))}</label><select id="recommendDiet">${this._recommendDietOptions()}</select></div>
        <div class="field grow"><label>${this._escape(this._t("recommendQuery"))}</label><input id="recommendQuery" value="${this._escape(this._recommendQuery)}" placeholder="${this._escape(this._t("recommendQueryPlaceholder"))}"></div>
        <button id="recommendBtn" class="btn">${this._escape(this._t("recommendBtn"))}</button>
      </div>
    </section>${this._detailHtml(this._opened)}<div id="recipeGrid" class="grid" style="margin-top:14px"></div>`;

    const section=c.querySelector("section.card");
    if(section)this._bindLocaleControls(section);
    c.querySelector("#recommendDiet")?.addEventListener("change",event=>{
      this._recommendDiet=String(event.target.value||"profile");
    });
    c.querySelector("#recommendQuery")?.addEventListener("input",event=>{
      this._recommendQuery=String(event.target.value||"");
    });
    c.querySelector("#recommendQuery")?.addEventListener("keydown",event=>{
      if(event.key==="Enter")void this._recommend();
    });
    c.querySelector("#recommendBtn")?.addEventListener("click",()=>void this._recommend());

    this._bindDetail(c);
    const grid=c.querySelector("#recipeGrid");
    if(this._recommendations.length){
      grid.innerHTML=this._recommendations.map(recipe=>this._recipeCard(recipe,false)).join("");
      this._bindCards(grid,this._recommendations,false);
    }
  }

  async _recommend(){
    this._opened=null;
    try{
      this._message(this._t("loading"));
      const result=await this._api("cook4me/v13/recommend",{
        entry_id:this._entryId,
        query:String(this._recommendQuery||"").trim(),
        diet:this._recommendDiet||"profile",
        limit:24,
        catalog_size:50,
        language:this._selectedLanguage(),
        strict_language:this._strictLanguage(),
      });
      const items=result?.items||[];
      items.forEach(recipe=>this._ensureRecipeSelections(recipe));
      if(this._shouldTranslate()&&items.some(recipe=>this._translationNeeded(recipe))){
        this._message(this._t("translating"));
        await this._translateItems(items);
      }
      this._recommendations=items;
      this._message("");
      this._renderTab();
    }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
  }
}

customElements.define("cook4me-recipe-hub-panel-v15",Cook4MeRecipeHubPanelV15);

})();

// cook4me-panel-v16.js
(() => {

const BasePanel = customElements.get("cook4me-recipe-hub-panel-v15");

const TEXT = {
  en:{
    stock:"House stock",stockHelp:"Select an ingredient, enter what you bought, or mark it unlimited. Adding an ingredient you already have increases its current amount.",
    amount:"Amount",unit:"Unit",unlimited:"Unlimited (∞)",addStock:"Add to house stock",updateStock:"Update",removeStock:"Remove",
    stockUnknown:"amount not set",consumeTitle:"Confirm consumed ingredients",consumeHelp:"The recipe finished successfully. Each ingredient defaults to Yes and to the amount required by the recipe. Edit anything before confirming.",
    consume:"Consumed",confirmConsumption:"Confirm deductions",nothingConsumed:"Nothing was consumed",recipeAmount:"Recipe amount",currentStock:"Current stock",
    stockUpdated:"House stock updated",consumptionUpdated:"House stock deductions confirmed",
  },
  de:{
    stock:"Vorrat zu Hause",stockHelp:"Zutat auswählen und gekaufte Menge eintragen oder als unbegrenzt markieren. Bei einer bereits vorhandenen Zutat wird die Menge addiert.",
    amount:"Menge",unit:"Einheit",unlimited:"Unbegrenzt (∞)",addStock:"Zum Vorrat hinzufügen",updateStock:"Aktualisieren",removeStock:"Entfernen",
    stockUnknown:"Menge nicht gesetzt",consumeTitle:"Verbrauchte Zutaten bestätigen",consumeHelp:"Das Rezept wurde erfolgreich beendet. Jede Zutat steht standardmäßig auf Ja und auf der im Rezept benötigten Menge. Vor dem Bestätigen kann alles geändert werden.",
    consume:"Verbraucht",confirmConsumption:"Abzüge bestätigen",nothingConsumed:"Nichts wurde verbraucht",recipeAmount:"Rezeptmenge",currentStock:"Aktueller Vorrat",
    stockUpdated:"Vorrat aktualisiert",consumptionUpdated:"Vorratsabzüge bestätigt",
  },
  el:{
    stock:"Απόθεμα στο σπίτι",stockHelp:"Επίλεξε υλικό και βάλε την ποσότητα που αγόρασες ή όρισέ το ως απεριόριστο. Αν υπάρχει ήδη, η νέα ποσότητα προστίθεται στην υπάρχουσα.",
    amount:"Ποσότητα",unit:"Μονάδα",unlimited:"Απεριόριστο (∞)",addStock:"Προσθήκη στο απόθεμα",updateStock:"Ενημέρωση",removeStock:"Αφαίρεση",
    stockUnknown:"χωρίς ποσότητα",consumeTitle:"Επιβεβαίωση κατανάλωσης υλικών",consumeHelp:"Η συνταγή ολοκληρώθηκε επιτυχώς. Κάθε υλικό είναι προεπιλεγμένο σε Ναι και στην ποσότητα που απαιτούσε η συνταγή. Μπορείς να αλλάξεις κάθε ποσότητα πριν την επιβεβαίωση.",
    consume:"Καταναλώθηκε",confirmConsumption:"Επιβεβαίωση αφαίρεσης",nothingConsumed:"Δεν καταναλώθηκε τίποτα",recipeAmount:"Ποσότητα συνταγής",currentStock:"Τρέχον απόθεμα",
    stockUpdated:"Το απόθεμα ενημερώθηκε",consumptionUpdated:"Οι αφαιρέσεις από το απόθεμα επιβεβαιώθηκαν",
  },
};

class Cook4MeRecipeHubPanelV16 extends BasePanel {
  constructor(){
    super();
    this._pendingConsumption=null;
    this._inventoryLoadedEntry="";
    this._inventoryLoading=false;
  }

  _t(key){return TEXT[this._langCode()]?.[key]||TEXT.en[key]||super._t(key);}

  _ensureHouseState(){
    if(this._houseEntryId===this._entryId)return;
    const profile=this._entry()?.profile||{};
    const rows=Array.isArray(profile.houseIngredients)&&profile.houseIngredients.length
      ?profile.houseIngredients
      :(profile.pantry||[]).map(name=>({name:String(name)}));
    this._houseIngredients=rows.map(row=>typeof row==="object"&&row?{...row}:{name:String(row||"")}).filter(row=>String(row.name||"").trim());
    this._houseEntryId=this._entryId||"";
    this._ingredientCatalog=[];
    this._ingredientCatalogLanguage="";
    this._pendingConsumption=null;
    this._inventoryLoadedEntry="";
  }

  _stockIdentity(row){return row?.key?`k:${row.key}`:`n:${String(row?.name||"").trim().toLocaleLowerCase()}`;}

  _stockText(row){
    if(row?.unlimited)return "∞";
    if(row?.quantity===undefined||row?.quantity===null||row?.quantity==="")return this._t("stockUnknown");
    const amount=Number(row.quantity);
    const shown=Number.isFinite(amount)?(Number.isInteger(amount)?String(amount):String(Number(amount.toFixed(6)))):String(row.quantity);
    return `${shown}${row?.unit?` ${row.unit}`:""}`;
  }

  _syncEntryProfile(){
    const entry=this._entry();
    if(!entry)return;
    entry.profile={...(entry.profile||{}),houseIngredients:this._houseIngredients.map(row=>({...row})),pantry:this._houseIngredients.map(row=>row.name)};
  }

  async _loadInventoryState(){
    if(!this._entryId||this._inventoryLoading)return;
    this._inventoryLoading=true;
    try{
      const result=await this._api("cook4me/v14/inventory_state",{entry_id:this._entryId});
      this._houseIngredients=Array.isArray(result?.houseIngredients)?result.houseIngredients:[];
      this._pendingConsumption=result?.pendingConsumption||null;
      this._inventoryLoadedEntry=this._entryId;
      this._syncEntryProfile();
      if(this._tab==="profile")this._renderTab();
    }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
    finally{this._inventoryLoading=false;}
  }

  _renderHouseChoices(c){
    const select=c.querySelector("#houseCatalog");
    if(!select)return;
    const q=String(this._houseFilter||"").trim().toLocaleLowerCase();
    const rows=this._ingredientCatalog.filter(row=>!q||String(row.name||"").toLocaleLowerCase().includes(q));
    select.innerHTML=rows.map((row,index)=>`<option value="${index}">${this._escape(row.name||"")}</option>`).join("");
    select._cook4meRows=rows;
  }

  _inventoryRowsHtml(){
    if(!this._houseIngredients.length)return `<div class="muted">${this._escape(this._t("houseEmpty"))}</div>`;
    return this._houseIngredients.map((row,index)=>{
      const unlimited=Boolean(row.unlimited);
      const amount=row.quantity===undefined||row.quantity===null?"":row.quantity;
      return `<div data-stock-row="${index}" style="display:grid;grid-template-columns:minmax(180px,1fr) minmax(90px,140px) minmax(80px,130px) auto auto;gap:8px;align-items:end;padding:10px 0;border-bottom:1px solid var(--divider-color)">
        <div><strong>${this._escape(row.name||"")}</strong> <span class="muted">(${this._escape(this._stockText(row))})</span></div>
        <div class="field"><label>${this._escape(this._t("amount"))}</label><input data-stock-amount type="number" min="0" step="any" value="${this._escape(amount)}" ${unlimited?"disabled":""}></div>
        <div class="field"><label>${this._escape(this._t("unit"))}</label><input data-stock-unit value="${this._escape(row.unit||"")}" list="cook4meStockUnits"></div>
        <label style="display:flex;align-items:center;gap:6px;min-height:42px"><input data-stock-unlimited type="checkbox" ${unlimited?"checked":""}> ${this._escape(this._t("unlimited"))}</label>
        <div style="display:flex;gap:6px"><button class="btn secondary" data-stock-save>${this._escape(this._t("updateStock"))}</button><button class="btn secondary" data-stock-remove>${this._escape(this._t("removeStock"))}</button></div>
      </div>`;
    }).join("");
  }

  _renderInventoryOnly(c){
    const target=c.querySelector("#houseInventoryRows");
    if(!target)return;
    target.innerHTML=this._inventoryRowsHtml();
    this._bindInventoryRows(c);
  }

  _bindInventoryRows(c){
    c.querySelectorAll("[data-stock-row]").forEach(container=>{
      const index=Number(container.dataset.stockRow); const row=this._houseIngredients[index]; if(!row)return;
      const unlimited=container.querySelector("[data-stock-unlimited]");
      const amount=container.querySelector("[data-stock-amount]");
      unlimited?.addEventListener("change",()=>{if(amount)amount.disabled=Boolean(unlimited.checked);});
      container.querySelector("[data-stock-save]")?.addEventListener("click",async()=>{
        try{
          const result=await this._api("cook4me/v14/inventory_update",{
            entry_id:this._entryId,identity:this._stockIdentity(row),
            ...(amount?.value!==""?{quantity:amount.value}:{}),
            unit:String(container.querySelector("[data-stock-unit]")?.value||""),
            unlimited:Boolean(unlimited?.checked),
          });
          this._houseIngredients=result?.houseIngredients||[]; this._syncEntryProfile(); this._renderInventoryOnly(c); this._message(this._t("stockUpdated"));
        }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
      });
      container.querySelector("[data-stock-remove]")?.addEventListener("click",async()=>{
        try{
          const result=await this._api("cook4me/v14/inventory_remove",{entry_id:this._entryId,identity:this._stockIdentity(row)});
          this._houseIngredients=result?.houseIngredients||[]; this._syncEntryProfile(); this._renderInventoryOnly(c); this._message(this._t("stockUpdated"));
        }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
      });
    });
  }

  _pendingHtml(){
    const pending=this._pendingConsumption;
    if(!pending?.id)return "";
    const rows=(pending.ingredients||[]).map((row,index)=>{
      const unlimited=Boolean(row.stockUnlimited);
      const amount=row.quantity===undefined||row.quantity===null?"":row.quantity;
      return `<div data-consume-row="${index}" style="display:grid;grid-template-columns:auto minmax(180px,1fr) minmax(90px,140px) minmax(80px,130px);gap:8px;align-items:end;padding:9px 0;border-bottom:1px solid var(--divider-color)">
        <label style="display:flex;align-items:center;gap:6px;min-height:42px"><input data-consume-check type="checkbox" checked ${unlimited?"disabled":""}> ${this._escape(this._t("consume"))}</label>
        <div><strong>${this._escape(row.name||"")}</strong><div class="muted">${this._escape(this._t("currentStock"))}: ${this._escape(unlimited?"∞":`${row.stockQuantity??"?"}${row.stockUnit?` ${row.stockUnit}`:""}`)}</div></div>
        <div class="field"><label>${this._escape(this._t("recipeAmount"))}</label><input data-consume-amount type="number" min="0" step="any" value="${this._escape(amount)}" ${unlimited?"disabled":""}></div>
        <div class="field"><label>${this._escape(this._t("unit"))}</label><input data-consume-unit value="${this._escape(row.unit||"")}" list="cook4meStockUnits" ${unlimited?"disabled":""}></div>
      </div>`;
    }).join("");
    return `<section class="card" style="border-left:4px solid var(--primary-color)"><h2 style="margin-top:0">${this._escape(this._t("consumeTitle"))}</h2><div class="muted"><strong>${this._escape(pending.recipeTitle||"")}</strong> · ${this._escape(this._t("consumeHelp"))}</div><div style="margin-top:10px">${rows}</div><div class="toolbar" style="margin-top:12px"><button id="confirmConsumption" class="btn">${this._escape(this._t("confirmConsumption"))}</button><button id="clearConsumption" class="btn secondary">${this._escape(this._t("nothingConsumed"))}</button></div></section>`;
  }

  _bindPending(c){
    const pending=this._pendingConsumption; if(!pending?.id)return;
    c.querySelector("#confirmConsumption")?.addEventListener("click",async()=>{
      const ingredients=[];
      c.querySelectorAll("[data-consume-row]").forEach(container=>{
        const index=Number(container.dataset.consumeRow); const row=pending.ingredients[index]; if(!row)return;
        const unlimited=Boolean(row.stockUnlimited);
        ingredients.push({identity:row.identity,key:row.key,name:row.name,consume:unlimited?true:Boolean(container.querySelector("[data-consume-check]")?.checked),quantity:container.querySelector("[data-consume-amount]")?.value||null,unit:String(container.querySelector("[data-consume-unit]")?.value||"")});
      });
      try{
        const result=await this._api("cook4me/v14/consumption_confirm",{entry_id:this._entryId,pending_id:pending.id,ingredients});
        this._houseIngredients=result?.houseIngredients||result?.profile?.houseIngredients||[]; this._pendingConsumption=null; this._syncEntryProfile(); this._message(this._t("consumptionUpdated")); this._renderProfile(c);
      }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
    });
    c.querySelector("#clearConsumption")?.addEventListener("click",async()=>{
      try{
        await this._api("cook4me/v14/consumption_clear",{entry_id:this._entryId,pending_id:pending.id});
        this._pendingConsumption=null; this._renderProfile(c);
      }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
    });
  }

  _renderProfile(c){
    this._ensureHouseState();
    const e=this._entry()||{}; const p=e.profile||{}; const join=x=>(x||[]).join("\n"); const habits=e.habitTerms||[];
    const defaultLanguage=String(this._capabilities?.ingredientCatalogLanguage||this._capabilities?.deviceCatalogLanguage||"de").toLowerCase();
    if(!this._ingredientCatalogLanguage)this._ingredientCatalogLanguage=defaultLanguage;
    if(!this._ingredientCatalog.length&&!this._ingredientCatalogLoading)queueMicrotask(()=>void this._loadIngredientCatalog(this._ingredientCatalogLanguage));
    if(this._inventoryLoadedEntry!==this._entryId&&!this._inventoryLoading)queueMicrotask(()=>void this._loadInventoryState());
    c.innerHTML=`${this._pendingHtml()}<section class="card"><div class="formgrid">
      <div class="field"><label>${this._t("diet")}</label><select id="diet"><option value="omnivore">${this._t("omnivore")}</option><option value="pescatarian">${this._t("pescatarian")}</option><option value="vegetarian">${this._t("vegetarian")}</option><option value="vegan">${this._t("vegan")}</option></select></div><div></div>
      <div class="field wide"><details><summary style="cursor:pointer;font-weight:600">${this._escape(this._t("stock"))} (${this._houseIngredients.length})</summary><div class="muted" style="margin:8px 0">${this._escape(this._t("stockHelp"))}</div><div id="houseInventoryRows">${this._inventoryRowsHtml()}</div></details></div>
      <div class="field"><label>${this._escape(this._t("ingredientCatalog"))}</label><select id="ingredientLanguage">${this._catalogLanguageOptions()}</select></div>
      <div class="field"><label>${this._escape(this._t("ingredientSearch"))}</label><input id="houseSearch" value="${this._escape(this._houseFilter)}" placeholder="${this._escape(this._t("ingredientSearch"))}"></div>
      <div class="field wide"><select id="houseCatalog" size="8" style="min-height:180px"></select></div>
      <div class="field"><label>${this._escape(this._t("amount"))}</label><input id="stockAddAmount" type="number" min="0" step="any"></div>
      <div class="field"><label>${this._escape(this._t("unit"))}</label><input id="stockAddUnit" list="cook4meStockUnits"><datalist id="cook4meStockUnits"><option value="g"><option value="kg"><option value="ml"><option value="l"><option value="pcs"></datalist></div>
      <div class="field wide"><label style="display:flex;align-items:center;gap:8px"><input id="stockAddUnlimited" type="checkbox"> ${this._escape(this._t("unlimited"))}</label><button id="houseAdd" type="button" class="btn secondary" style="margin-top:8px">${this._escape(this._t("addStock"))}</button>${this._ingredientCatalogLoading?`<span class="muted">${this._escape(this._t("catalogLoading"))}</span>`:""}</div>
      <div class="field"><label>${this._t("allergies")}</label><textarea id="allergies">${this._escape(join(p.allergies))}</textarea></div>
      <div class="field"><label>${this._t("avoid")}</label><textarea id="avoid">${this._escape(join(p.avoid))}</textarea></div>
      <div class="field wide"><label>${this._t("preferences")}</label><textarea id="preferences">${this._escape(join(p.preferences))}</textarea></div>
      ${habits.length?`<div class="field wide"><label>${this._t("learnedHabits")}</label><div class="chips">${habits.map(x=>`<span class="chip">♥ ${this._escape(x)}</span>`).join("")}</div></div>`:""}
      </div><button id="profileSave" class="btn">${this._t("save")}</button></section>`;
    c.querySelector("#diet").value=p.diet||"omnivore";
    this._renderHouseChoices(c); this._bindInventoryRows(c); this._bindPending(c);
    c.querySelector("#houseSearch")?.addEventListener("input",event=>{this._houseFilter=String(event.target.value||"");this._renderHouseChoices(c);});
    c.querySelector("#ingredientLanguage")?.addEventListener("change",event=>{this._houseFilter="";void this._loadIngredientCatalog(String(event.target.value||defaultLanguage));});
    const unlimited=c.querySelector("#stockAddUnlimited"); const amount=c.querySelector("#stockAddAmount");
    unlimited?.addEventListener("change",()=>{if(amount)amount.disabled=Boolean(unlimited.checked);});
    c.querySelector("#houseCatalog")?.addEventListener("change",event=>{
      const rows=event.target?._cook4meRows||[]; const selected=rows[Number(event.target.value)]; if(!selected)return;
      const existing=this._houseIngredients.find(row=>this._stockIdentity(row)===this._stockIdentity(selected));
      if(existing&&c.querySelector("#stockAddUnit")&&!c.querySelector("#stockAddUnit").value)c.querySelector("#stockAddUnit").value=existing.unit||"";
    });
    c.querySelector("#houseAdd")?.addEventListener("click",async()=>{
      const select=c.querySelector("#houseCatalog"); const rows=select?._cook4meRows||[]; const row=rows[Number(select?.value)]; if(!row)return;
      const scrollTop=select.scrollTop; const selectedValue=select.value;
      try{
        const result=await this._api("cook4me/v14/inventory_add",{entry_id:this._entryId,ingredient:row,...(amount?.value!==""?{quantity:amount.value}:{}),unit:String(c.querySelector("#stockAddUnit")?.value||""),unlimited:Boolean(unlimited?.checked)});
        this._houseIngredients=result?.houseIngredients||[]; this._syncEntryProfile(); this._renderInventoryOnly(c); select.value=selectedValue; select.scrollTop=scrollTop; if(amount)amount.value=""; this._message(this._t("stockUpdated"));
      }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
    });
    c.querySelector("#profileSave")?.addEventListener("click",async()=>{
      const profile={diet:c.querySelector("#diet")?.value||"omnivore",allergies:this._splitList(c.querySelector("#allergies")?.value||""),avoid:this._splitList(c.querySelector("#avoid")?.value||""),preferences:this._splitList(c.querySelector("#preferences")?.value||"")};
      try{await this._api("cook4me/profile_save",{entry_id:this._entryId,profile});const entry=this._entry();if(entry)entry.profile={...(entry.profile||{}),...profile};this._message(this._t("save"));}catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
    });
  }
}

customElements.define("cook4me-recipe-hub-panel-v16",Cook4MeRecipeHubPanelV16);

})();

// cook4me-panel-v17.js
(() => {

const BasePanel = customElements.get("cook4me-recipe-hub-panel-v16");

const TEXT = {
  en:{
    scanShopping:"Scan shopping",scanHelp:"Keep the camera open and scan each product barcode. Known products are added immediately; unknown products need one mapping, then future scans are automatic.",
    startScanner:"Start camera scanner",stopScanner:"Stop scanner",cameraUnsupported:"Live barcode scanning is not supported by this browser. You can still enter the barcode below.",
    cameraError:"Could not open the camera",barcode:"Barcode",scanBarcode:"Scan / look up",lookingUp:"Looking up product…",scanReady:"Point the rear camera at an EAN/UPC barcode.",
    scannedAdded:"Added to house stock",mapProduct:"Map this product once",mapHelp:"Choose the Cook4Me ingredient and package amount. This barcode will be remembered for future automatic scans.",
    product:"Product",packageAmount:"Package amount",mapAndAdd:"Save mapping & add",unknownProduct:"Unknown product",chooseIngredient:"Cook4Me ingredient",invalidIngredient:"Choose an ingredient from the Cook4Me catalog.",
  },
  de:{
    scanShopping:"Einkauf scannen",scanHelp:"Kamera geöffnet lassen und nacheinander die Barcodes der Einkäufe scannen. Bekannte Produkte werden sofort addiert; unbekannte Produkte müssen nur einmal zugeordnet werden.",
    startScanner:"Kamera-Scanner starten",stopScanner:"Scanner stoppen",cameraUnsupported:"Dieser Browser unterstützt keinen Live-Barcodescanner. Der Barcode kann unten weiterhin eingegeben werden.",
    cameraError:"Kamera konnte nicht geöffnet werden",barcode:"Barcode",scanBarcode:"Scannen / suchen",lookingUp:"Produkt wird gesucht…",scanReady:"EAN/UPC-Barcode vor die Rückkamera halten.",
    scannedAdded:"Zum Vorrat hinzugefügt",mapProduct:"Produkt einmal zuordnen",mapHelp:"Cook4Me-Zutat und Packungsmenge wählen. Dieser Barcode wird danach bei jedem Scan automatisch erkannt.",
    product:"Produkt",packageAmount:"Packungsmenge",mapAndAdd:"Zuordnung speichern & hinzufügen",unknownProduct:"Unbekanntes Produkt",chooseIngredient:"Cook4Me-Zutat",invalidIngredient:"Bitte eine Zutat aus dem Cook4Me-Katalog auswählen.",
  },
  el:{
    scanShopping:"Σάρωση αγορών",scanHelp:"Άφησε την κάμερα ανοιχτή και σκάναρε διαδοχικά το barcode κάθε προϊόντος. Τα γνωστά προϊόντα προστίθενται αμέσως· τα άγνωστα χρειάζονται αντιστοίχιση μόνο την πρώτη φορά.",
    startScanner:"Έναρξη scanner κάμερας",stopScanner:"Διακοπή scanner",cameraUnsupported:"Ο browser δεν υποστηρίζει live σάρωση barcode. Μπορείς ακόμη να εισαγάγεις τον barcode παρακάτω.",
    cameraError:"Δεν ήταν δυνατό να ανοίξει η κάμερα",barcode:"Barcode",scanBarcode:"Σάρωση / αναζήτηση",lookingUp:"Αναζήτηση προϊόντος…",scanReady:"Στρέψε την πίσω κάμερα σε barcode EAN/UPC.",
    scannedAdded:"Προστέθηκε στο απόθεμα",mapProduct:"Αντιστοίχιση προϊόντος μία φορά",mapHelp:"Επίλεξε το υλικό Cook4Me και την ποσότητα συσκευασίας. Ο barcode θα θυμάται την αντιστοίχιση για τις επόμενες σαρώσεις.",
    product:"Προϊόν",packageAmount:"Ποσότητα συσκευασίας",mapAndAdd:"Αποθήκευση αντιστοίχισης & προσθήκη",unknownProduct:"Άγνωστο προϊόν",chooseIngredient:"Υλικό Cook4Me",invalidIngredient:"Επίλεξε υλικό από τον κατάλογο Cook4Me.",
  },
};

class Cook4MeRecipeHubPanelV17 extends BasePanel {
  constructor(){
    super();
    this._scannerOpen=false;
    this._scannerStream=null;
    this._scannerDetector=null;
    this._scannerTimer=null;
    this._scannerBusy=false;
    this._scannerStatus="";
    this._scannerResult=null;
    this._scannerLastCode="";
    this._scannerLastAt=0;
  }

  _t(key){return TEXT[this._langCode()]?.[key]||TEXT.en[key]||super._t(key);}

  _stopBarcodeCamera(close=false){
    if(this._scannerTimer){clearTimeout(this._scannerTimer);this._scannerTimer=null;}
    if(this._scannerStream){
      for(const track of this._scannerStream.getTracks?.()||[])track.stop();
      this._scannerStream=null;
    }
    this._scannerDetector=null;
    if(close)this._scannerOpen=false;
  }

  _renderTab(){
    if(this._tab!=="profile")this._stopBarcodeCamera(true);
    super._renderTab();
  }

  _scannerHtml(){
    return `<div class="field wide" id="shoppingScannerBlock" style="border:1px solid var(--divider-color);border-radius:14px;padding:14px">
      <div class="detail-head"><div><h3 style="margin:0">📷 ${this._escape(this._t("scanShopping"))}</h3><div class="muted" style="margin-top:4px">${this._escape(this._t("scanHelp"))}</div></div>
      <button id="scannerToggle" type="button" class="btn secondary">${this._escape(this._scannerOpen?this._t("stopScanner"):this._t("startScanner"))}</button></div>
      ${this._scannerOpen?`<div style="margin-top:12px">
        <video id="shoppingScannerVideo" playsinline autoplay muted style="width:100%;max-height:340px;object-fit:cover;background:#000;border-radius:12px"></video>
        <div id="scannerStatus" class="muted" style="margin:8px 0">${this._escape(this._scannerStatus||this._t("scanReady"))}</div>
        <div class="toolbar"><input id="manualBarcode" class="grow" inputmode="numeric" autocomplete="off" placeholder="${this._escape(this._t("barcode"))}"><button id="manualBarcodeBtn" type="button" class="btn secondary">${this._escape(this._t("scanBarcode"))}</button></div>
        <div id="scannerResult" style="margin-top:10px">${this._scannerResultHtml()}</div>
      </div>`:""}
    </div>`;
  }

  _scannerResultHtml(){
    const result=this._scannerResult;
    if(!result)return "";
    if(result.status==="added"){
      const mapping=result.mapping||{}; const ingredient=mapping.ingredient||{};
      const amount=mapping.quantity!==undefined&&mapping.quantity!==null?`${mapping.quantity}${mapping.unit?` ${mapping.unit}`:""}`:"";
      const product=mapping.productName||result.product?.productName||ingredient.name||result.barcode;
      return `<div class="notice">✓ ${this._escape(this._t("scannedAdded"))}: <strong>${this._escape(product)}</strong> → ${this._escape(ingredient.name||"")} ${amount?`(${this._escape(amount)})`:""}</div>`;
    }
    if(result.status!=="needs_mapping")return "";
    const product=result.product||{};
    const first=result.suggestions?.[0]?.ingredient||result.mapping?.ingredient||{};
    const defaultName=String(first.name||"");
    const quantity=product.quantity??result.mapping?.quantity??1;
    const unit=String(product.unit||result.mapping?.unit||"pcs");
    const options=(this._ingredientCatalog||[]).map(row=>`<option value="${this._escape(row.name||"")}"></option>`).join("");
    const productName=product.productName||product.name||result.mapping?.productName||this._t("unknownProduct");
    const brand=product.brand||result.mapping?.brand||"";
    return `<div class="card" style="padding:12px;margin:0">
      <h3 style="margin:0 0 4px">${this._escape(this._t("mapProduct"))}</h3>
      <div class="muted">${this._escape(this._t("mapHelp"))}</div>
      <div style="margin:10px 0"><strong>${this._escape(this._t("product"))}:</strong> ${this._escape(productName)}${brand?` · ${this._escape(brand)}`:""}<br><span class="muted">${this._escape(result.barcode||"")}${product.rawQuantity?` · ${this._escape(product.rawQuantity)}`:""}</span></div>
      <div class="formgrid">
        <div class="field wide"><label>${this._escape(this._t("chooseIngredient"))}</label><input id="scanIngredientName" list="scanIngredientCatalog" value="${this._escape(defaultName)}"><datalist id="scanIngredientCatalog">${options}</datalist></div>
        <div class="field"><label>${this._escape(this._t("packageAmount"))}</label><input id="scanPackageAmount" type="number" min="0" step="any" value="${this._escape(quantity)}"></div>
        <div class="field"><label>${this._escape(this._t("unit"))}</label><input id="scanPackageUnit" value="${this._escape(unit)}" list="cook4meStockUnits"></div>
      </div>
      <button id="scanMapAdd" type="button" class="btn" style="margin-top:8px">${this._escape(this._t("mapAndAdd"))}</button>
    </div>`;
  }

  _renderScannerResult(c){
    const target=c.querySelector("#scannerResult");
    if(target){target.innerHTML=this._scannerResultHtml();this._bindScannerMapping(c);}
    const status=c.querySelector("#scannerStatus");
    if(status)status.textContent=this._scannerStatus||this._t("scanReady");
  }

  _catalogRowByName(name){
    const target=String(name||"").trim().toLocaleLowerCase();
    return (this._ingredientCatalog||[]).find(row=>String(row?.name||"").trim().toLocaleLowerCase()===target)||null;
  }

  _bindScannerMapping(c){
    c.querySelector("#scanMapAdd")?.addEventListener("click",async()=>{
      const result=this._scannerResult; if(!result?.barcode)return;
      const name=String(c.querySelector("#scanIngredientName")?.value||"").trim();
      const ingredient=this._catalogRowByName(name);
      if(!ingredient){this._scannerStatus=this._t("invalidIngredient");this._renderScannerResult(c);return;}
      const quantity=String(c.querySelector("#scanPackageAmount")?.value||"").trim();
      const unit=String(c.querySelector("#scanPackageUnit")?.value||"").trim();
      if(!quantity)return;
      this._scannerBusy=true;this._scannerStatus=this._t("lookingUp");this._renderScannerResult(c);
      try{
        const mapped=await this._api("cook4me/v15/barcode_map_add",{
          entry_id:this._entryId,barcode:String(result.barcode),ingredient,
          quantity,unit,product_name:String(result.product?.productName||result.product?.name||""),brand:String(result.product?.brand||""),
        });
        this._houseIngredients=mapped?.houseIngredients||[];this._syncEntryProfile();this._renderInventoryOnly(c);
        this._scannerResult=mapped;this._scannerStatus=this._t("scannedAdded");navigator.vibrate?.(80);
      }catch(e){this._scannerStatus=`${this._t("error")}: ${e.message||e}`;}
      finally{this._scannerBusy=false;this._renderScannerResult(c);}
    });
  }

  async _handleBarcode(code,c){
    code=String(code||"").replace(/[\s-]+/g,"");
    if(!code||this._scannerBusy)return;
    const now=Date.now();
    if(code===this._scannerLastCode&&now-this._scannerLastAt<1200)return;
    this._scannerLastCode=code;this._scannerLastAt=now;
    this._scannerBusy=true;this._scannerStatus=this._t("lookingUp");this._renderScannerResult(c);
    try{
      const result=await this._api("cook4me/v15/barcode_scan",{
        entry_id:this._entryId,barcode:code,language:this._ingredientCatalogLanguage||this._capabilities?.deviceCatalogLanguage||"de",
      });
      this._scannerResult=result;
      this._houseIngredients=result?.houseIngredients||this._houseIngredients;this._syncEntryProfile();this._renderInventoryOnly(c);
      if(result?.status==="added"){
        this._scannerStatus=this._t("scannedAdded");navigator.vibrate?.(80);
      }else{
        this._scannerStatus=this._t("mapProduct");navigator.vibrate?.([40,40,40]);
      }
    }catch(e){this._scannerStatus=`${this._t("error")}: ${e.message||e}`;}
    finally{this._scannerBusy=false;this._renderScannerResult(c);}
  }

  async _startBarcodeCamera(c){
    if(!this._scannerOpen||this._scannerStream)return;
    const video=c.querySelector("#shoppingScannerVideo"); if(!video)return;
    if(!navigator.mediaDevices?.getUserMedia||!("BarcodeDetector" in globalThis)){
      this._scannerStatus=this._t("cameraUnsupported");this._renderScannerResult(c);return;
    }
    try{
      let formats=[];
      try{
        const supported=await BarcodeDetector.getSupportedFormats();
        formats=["ean_13","ean_8","upc_a","upc_e","itf"].filter(format=>supported.includes(format));
      }catch(_e){}
      this._scannerDetector=formats.length?new BarcodeDetector({formats}):new BarcodeDetector();
      this._scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}},audio:false});
      video.srcObject=this._scannerStream;await video.play();
      this._scannerStatus=this._t("scanReady");this._renderScannerResult(c);
      const tick=async()=>{
        if(!this._scannerOpen||!this._scannerDetector||!this._scannerStream)return;
        if(!this._scannerBusy&&video.readyState>=2){
          try{
            const found=await this._scannerDetector.detect(video);
            const code=found?.[0]?.rawValue;
            if(code)void this._handleBarcode(code,c);
          }catch(_e){}
        }
        this._scannerTimer=setTimeout(tick,180);
      };
      tick();
    }catch(e){
      this._stopBarcodeCamera(false);
      this._scannerStatus=`${this._t("cameraError")}: ${e.message||e}`;this._renderScannerResult(c);
    }
  }

  _bindScanner(c){
    c.querySelector("#scannerToggle")?.addEventListener("click",()=>{
      if(this._scannerOpen){this._stopBarcodeCamera(true);this._scannerStatus="";this._scannerResult=null;this._renderProfile(c);}
      else{this._scannerOpen=true;this._scannerStatus=this._t("scanReady");this._renderProfile(c);}
    });
    const manual=()=>{const code=String(c.querySelector("#manualBarcode")?.value||"").trim();if(code)void this._handleBarcode(code,c);};
    c.querySelector("#manualBarcodeBtn")?.addEventListener("click",manual);
    c.querySelector("#manualBarcode")?.addEventListener("keydown",event=>{if(event.key==="Enter")manual();});
    this._bindScannerMapping(c);
  }

  _renderProfile(c){
    this._stopBarcodeCamera(false);
    super._renderProfile(c);
    const grid=c.querySelector(".formgrid");
    if(!grid)return;
    grid.insertAdjacentHTML("afterbegin",this._scannerHtml());
    this._bindScanner(c);
    if(this._scannerOpen)queueMicrotask(()=>void this._startBarcodeCamera(c));
  }
}

customElements.define("cook4me-recipe-hub-panel-v17",Cook4MeRecipeHubPanelV17);

})();

// cook4me-panel-v18.js
(() => {

const BasePanel = customElements.get("cook4me-recipe-hub-panel-v17");

const TEXT = {
  en:{nativeScannerReady:"Home Assistant native scanner is open. Scan EAN/UPC products continuously.",unsupportedNativeCode:"This barcode type is not a supported shopping-product code. Scan an EAN/UPC barcode."},
  de:{nativeScannerReady:"Der native Home-Assistant-Scanner ist geöffnet. EAN/UPC-Produkte können nacheinander gescannt werden.",unsupportedNativeCode:"Dieser Barcode-Typ wird für Einkaufsprodukte nicht unterstützt. Bitte einen EAN/UPC-Barcode scannen."},
  el:{nativeScannerReady:"Ο native scanner του Home Assistant είναι ανοιχτός. Σκάναρε διαδοχικά προϊόντα EAN/UPC.",unsupportedNativeCode:"Αυτός ο τύπος barcode δεν υποστηρίζεται για προϊόντα αγορών. Σκάναρε EAN/UPC barcode."},
};

class Cook4MeRecipeHubPanelV18 extends BasePanel {
  constructor(){
    super();
    this._nativeScannerExternal=null;
    this._nativeScannerOriginalReceive=null;
    this._nativeScannerWrappedReceive=null;
    this._nativeScannerRequest=null;
    this._nativeScannerActive=false;
  }

  _t(key){return TEXT[this._langCode()]?.[key]||TEXT.en[key]||super._t(key);}

  _nativeBarcodeScannerAvailable(){
    const external=this._hass?.auth?.external;
    return Boolean(
      external?.config?.hasBarCodeScanner&&
      typeof external.fireMessage==="function"&&
      typeof external.receiveMessage==="function"
    );
  }

  _restoreNativeScannerReceiver(){
    const external=this._nativeScannerExternal;
    if(
      external&&
      this._nativeScannerWrappedReceive&&
      external.receiveMessage===this._nativeScannerWrappedReceive&&
      this._nativeScannerOriginalReceive
    ){
      external.receiveMessage=this._nativeScannerOriginalReceive;
    }
    this._nativeScannerExternal=null;
    this._nativeScannerOriginalReceive=null;
    this._nativeScannerWrappedReceive=null;
    this._nativeScannerRequest=null;
  }

  _stopNativeBarcodeScanner(sendClose=true){
    const external=this._nativeScannerExternal||this._hass?.auth?.external;
    if(sendClose&&this._nativeScannerActive&&typeof external?.fireMessage==="function"){
      try{external.fireMessage({type:"bar_code/close"});}catch(_e){}
    }
    this._nativeScannerActive=false;
    this._restoreNativeScannerReceiver();
  }

  _stopBarcodeCamera(close=false){
    this._stopNativeBarcodeScanner(true);
    super._stopBarcodeCamera(close);
  }

  async _onNativeBarcodeMessage(msg,c){
    if(!this._nativeScannerActive||!msg||msg.id!==this._nativeScannerRequest?.id)return;
    if(msg.command==="bar_code/aborted"){
      this._stopNativeBarcodeScanner(false);
      this._scannerOpen=false;
      this._scannerStatus="";
      this._renderTab();
      return;
    }
    if(msg.command!=="bar_code/scan_result")return;

    const format=String(msg.payload?.format||"").toLowerCase();
    const allowed=new Set(["ean_13","ean_8","upc_a","upc_e","itf"]);
    if(!allowed.has(format)){
      try{
        this._nativeScannerExternal?.fireMessage({
          type:"bar_code/notify",
          payload:{message:this._t("unsupportedNativeCode")},
        });
      }catch(_e){}
      return;
    }

    await this._handleBarcode(String(msg.payload?.rawValue||""),c);
    if(this._scannerResult?.status==="needs_mapping"){
      // The native overlay covers the panel. Close it while the user performs
      // the one-time mapping, then _bindScannerMapping restarts it automatically.
      this._stopNativeBarcodeScanner(true);
      this._renderScannerResult(c);
    }
  }

  async _startNativeBarcodeScanner(c){
    if(!this._scannerOpen||this._nativeScannerActive||!this._nativeBarcodeScannerAvailable())return;
    const external=this._hass.auth.external;
    const request={
      type:"bar_code/scan",
      payload:{
        title:this._t("scanShopping"),
        description:this._t("scanHelp"),
        alternative_option_label:this._t("stopScanner"),
      },
    };

    const original=external.receiveMessage;
    const wrapped=(msg)=>{
      // Let Home Assistant's normal external-app handler acknowledge and process
      // the command first. We only observe the matching scanner request.
      const result=original.call(external,msg);
      if(
        msg?.type==="command"&&
        (msg.command==="bar_code/scan_result"||msg.command==="bar_code/aborted")&&
        msg.id===request.id
      ){
        queueMicrotask(()=>void this._onNativeBarcodeMessage(msg,c));
      }
      return result;
    };

    this._nativeScannerExternal=external;
    this._nativeScannerOriginalReceive=original;
    this._nativeScannerWrappedReceive=wrapped;
    this._nativeScannerRequest=request;
    external.receiveMessage=wrapped;
    try{
      external.fireMessage(request);
      this._nativeScannerActive=true;
      this._scannerStatus=this._t("nativeScannerReady");
      this._renderScannerResult(c);
    }catch(e){
      this._stopNativeBarcodeScanner(false);
      this._scannerStatus=`${this._t("cameraError")}: ${e.message||e}`;
      this._renderScannerResult(c);
    }
  }

  async _startBarcodeCamera(c){
    if(this._nativeBarcodeScannerAvailable()){
      await this._startNativeBarcodeScanner(c);
      return;
    }
    await super._startBarcodeCamera(c);
  }

  _bindScannerMapping(c){
    c.querySelector("#scanMapAdd")?.addEventListener("click",async()=>{
      const result=this._scannerResult;if(!result?.barcode)return;
      const name=String(c.querySelector("#scanIngredientName")?.value||"").trim();
      const ingredient=this._catalogRowByName(name);
      if(!ingredient){this._scannerStatus=this._t("invalidIngredient");this._renderScannerResult(c);return;}
      const quantity=String(c.querySelector("#scanPackageAmount")?.value||"").trim();
      const unit=String(c.querySelector("#scanPackageUnit")?.value||"").trim();
      if(!quantity)return;
      this._scannerBusy=true;this._scannerStatus=this._t("lookingUp");this._renderScannerResult(c);
      try{
        const mapped=await this._api("cook4me/v15/barcode_map_add",{
          entry_id:this._entryId,barcode:String(result.barcode),ingredient,
          quantity,unit,product_name:String(result.product?.productName||result.product?.name||""),brand:String(result.product?.brand||""),
        });
        this._houseIngredients=mapped?.houseIngredients||[];
        this._syncEntryProfile();
        this._renderInventoryOnly(c);
        this._scannerResult=mapped;
        this._scannerStatus=this._t("scannedAdded");
        navigator.vibrate?.(80);
      }catch(e){
        this._scannerStatus=`${this._t("error")}: ${e.message||e}`;
      }finally{
        this._scannerBusy=false;
        this._renderScannerResult(c);
      }
      if(this._scannerOpen&&this._nativeBarcodeScannerAvailable()&&!this._nativeScannerActive){
        await this._startNativeBarcodeScanner(c);
      }
    });
  }
}

customElements.define("cook4me-recipe-hub-panel-v18",Cook4MeRecipeHubPanelV18);

})();

// cook4me-panel-v19.js
(() => {

const BasePanel = customElements.get("cook4me-recipe-hub-panel-v18");

const TEXT = {
  en:{
    suggestedIngredients:"Suggested Cook4Me ingredients",
    searchCatalog:"Search Cook4Me ingredient catalog",
    chooseFromCatalog:"Choose from Cook4Me catalog",
    catalogPickerHelp:"Likely matches are shown first. Search the full catalog if none is correct.",
    catalogPickerLoading:"Loading Cook4Me ingredient catalog…",
    catalogPickerEmpty:"No catalog ingredients match this search.",
    catalogShowing:"catalog matches shown",
  },
  de:{
    suggestedIngredients:"Vorgeschlagene Cook4Me-Zutaten",
    searchCatalog:"Cook4Me-Zutatenkatalog durchsuchen",
    chooseFromCatalog:"Aus dem Cook4Me-Katalog auswählen",
    catalogPickerHelp:"Wahrscheinliche Treffer stehen zuerst. Falls keiner passt, den vollständigen Katalog durchsuchen.",
    catalogPickerLoading:"Cook4Me-Zutatenkatalog wird geladen…",
    catalogPickerEmpty:"Keine Katalogzutat passt zu dieser Suche.",
    catalogShowing:"Katalogtreffer angezeigt",
  },
  el:{
    suggestedIngredients:"Προτεινόμενα υλικά Cook4Me",
    searchCatalog:"Αναζήτηση στον κατάλογο υλικών Cook4Me",
    chooseFromCatalog:"Επιλογή από τον κατάλογο Cook4Me",
    catalogPickerHelp:"Οι πιθανότερες αντιστοιχίσεις εμφανίζονται πρώτες. Αν καμία δεν είναι σωστή, αναζήτησε ολόκληρο τον κατάλογο.",
    catalogPickerLoading:"Φόρτωση καταλόγου υλικών Cook4Me…",
    catalogPickerEmpty:"Δεν βρέθηκε υλικό καταλόγου για αυτή την αναζήτηση.",
    catalogShowing:"αντιστοιχίσεις καταλόγου εμφανίζονται",
  },
};

class Cook4MeRecipeHubPanelV19 extends BasePanel {
  constructor(){
    super();
    this._scanIngredientFilter="";
    this._scanSelectedIngredient="";
    this._scanCatalogLoading=false;
  }

  _t(key){return TEXT[this._langCode()]?.[key]||TEXT.en[key]||super._t(key);}

  _scanIngredientIdentity(row){
    if(!row)return "";
    return row.key?`k:${String(row.key)}`:`n:${this._catalogVisualKey?this._catalogVisualKey(row.name):String(row.name||"").trim().toLocaleLowerCase()}`;
  }

  _scanNormalize(value){
    if(this._catalogVisualKey)return this._catalogVisualKey(value);
    return String(value||"").normalize("NFKD").replace(/\p{M}/gu,"").toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu," ").trim();
  }

  _scanSuggestions(){
    const out=[]; const seen=new Set();
    for(const item of this._scannerResult?.suggestions||[]){
      const row=item?.ingredient;
      if(!row?.name)continue;
      const id=this._scanIngredientIdentity(row); if(!id||seen.has(id))continue;
      seen.add(id);out.push({...row,_score:item.score,_reason:item.reason});
    }
    return out;
  }

  _scanCatalogRows(){
    const query=this._scanNormalize(this._scanIngredientFilter);
    const suggestions=this._scanSuggestions();
    const out=[]; const seen=new Set();
    const add=row=>{
      if(!row?.name)return;
      const id=this._scanIngredientIdentity(row);if(!id||seen.has(id))return;
      if(query&&!this._scanNormalize(row.name).includes(query))return;
      seen.add(id);out.push(row);
    };
    suggestions.forEach(add);
    for(const row of this._ingredientCatalog||[])add(row);
    return out.slice(0,120);
  }

  async _ensureScanCatalog(c){
    if(this._ingredientCatalog?.length||this._scanCatalogLoading||!this._entryId)return;
    this._scanCatalogLoading=true;
    try{
      const language=this._ingredientCatalogLanguage||this._capabilities?.ingredientCatalogLanguage||this._capabilities?.deviceCatalogLanguage||"de";
      const result=await this._api("cook4me/v11/ingredient_catalog",{entry_id:this._entryId,language:String(language),refresh:false});
      this._ingredientCatalog=Array.isArray(result?.items)?result.items:[];
      this._ingredientCatalogLanguage=String(result?.language||language).toLowerCase();
      if(typeof this._dedupeIngredientCatalog==="function")this._dedupeIngredientCatalog();
    }catch(e){
      this._scannerStatus=`${this._t("error")}: ${e.message||e}`;
    }finally{
      this._scanCatalogLoading=false;
      this._renderScannerResult(c);
    }
  }

  _scanPickerHtml(){
    const suggestions=this._scanSuggestions();
    const suggestionButtons=suggestions.length
      ?`<div style="margin:8px 0"><div class="muted" style="margin-bottom:6px">${this._escape(this._t("suggestedIngredients"))}</div><div class="chips">${suggestions.slice(0,8).map(row=>`<button type="button" class="chip" data-scan-suggestion="${this._escape(this._scanIngredientIdentity(row))}" style="cursor:pointer;border:1px solid var(--divider-color);background:var(--secondary-background-color);color:var(--primary-text-color)">${this._escape(row.name)}</button>`).join("")}</div></div>`:"";
    return `${suggestionButtons}
      <div class="muted" style="margin:6px 0">${this._escape(this._t("catalogPickerHelp"))}</div>
      <div class="field wide"><label>${this._escape(this._t("searchCatalog"))}</label><input id="scanIngredientFilter" value="${this._escape(this._scanIngredientFilter)}" autocomplete="off" placeholder="${this._escape(this._t("searchCatalog"))}"></div>
      <div class="field wide" style="margin-top:8px"><label>${this._escape(this._t("chooseFromCatalog"))}</label><select id="scanIngredientSelect" size="7" style="min-height:180px;width:100%"></select><div id="scanCatalogHint" class="muted" style="margin-top:4px"></div></div>`;
  }

  _scannerResultHtml(){
    const result=this._scannerResult;
    if(!result||result.status!=="needs_mapping")return super._scannerResultHtml();
    const product=result.product||{};
    const first=this._scanSuggestions()[0]||result.mapping?.ingredient||{};
    if(!this._scanSelectedIngredient&&first?.name)this._scanSelectedIngredient=this._scanIngredientIdentity(first);
    const quantity=product.quantity??result.mapping?.quantity??1;
    const unit=String(product.unit||result.mapping?.unit||"pcs");
    const productName=product.productName||product.name||result.mapping?.productName||this._t("unknownProduct");
    const brand=product.brand||result.mapping?.brand||"";
    return `<div class="card" style="padding:12px;margin:0">
      <h3 style="margin:0 0 4px">${this._escape(this._t("mapProduct"))}</h3>
      <div class="muted">${this._escape(this._t("mapHelp"))}</div>
      <div style="margin:10px 0"><strong>${this._escape(this._t("product"))}:</strong> ${this._escape(productName)}${brand?` · ${this._escape(brand)}`:""}<br><span class="muted">${this._escape(result.barcode||"")}${product.rawQuantity?` · ${this._escape(product.rawQuantity)}`:""}</span></div>
      ${this._scanPickerHtml()}
      <div class="formgrid" style="margin-top:10px">
        <div class="field"><label>${this._escape(this._t("packageAmount"))}</label><input id="scanPackageAmount" type="number" min="0" step="any" value="${this._escape(quantity)}"></div>
        <div class="field"><label>${this._escape(this._t("unit"))}</label><input id="scanPackageUnit" value="${this._escape(unit)}" list="cook4meStockUnits"></div>
      </div>
      <button id="scanMapAdd" type="button" class="btn" style="margin-top:8px">${this._escape(this._t("mapAndAdd"))}</button>
    </div>`;
  }

  _renderScanIngredientOptions(c){
    const select=c.querySelector("#scanIngredientSelect");if(!select)return;
    const rows=this._scanCatalogRows();
    select._cook4meRows=rows;
    select.innerHTML=rows.map((row,index)=>`<option value="${index}" ${this._scanIngredientIdentity(row)===this._scanSelectedIngredient?"selected":""}>${this._escape(row.name||"")}</option>`).join("");
    if(this._scanSelectedIngredient&&!rows.some(row=>this._scanIngredientIdentity(row)===this._scanSelectedIngredient)){
      this._scanSelectedIngredient="";
    }
    if(!this._scanSelectedIngredient&&rows.length){
      this._scanSelectedIngredient=this._scanIngredientIdentity(rows[0]);
      select.value="0";
    }
    const hint=c.querySelector("#scanCatalogHint");
    if(hint){
      hint.textContent=this._scanCatalogLoading?this._t("catalogPickerLoading"):(rows.length?`${rows.length} ${this._t("catalogShowing")}`:this._t("catalogPickerEmpty"));
    }
  }

  _selectedScanIngredient(c){
    const select=c.querySelector("#scanIngredientSelect");
    const rows=select?._cook4meRows||[];
    const row=rows[Number(select?.value)];
    return row?{...(row.key?{key:String(row.key)}:{}),name:String(row.name||"")}:null;
  }

  _bindScannerMapping(c){
    this._renderScanIngredientOptions(c);
    c.querySelector("#scanIngredientFilter")?.addEventListener("input",event=>{
      this._scanIngredientFilter=String(event.target.value||"");
      this._scanSelectedIngredient="";
      this._renderScanIngredientOptions(c);
    });
    c.querySelector("#scanIngredientSelect")?.addEventListener("change",event=>{
      const rows=event.target?._cook4meRows||[];
      const row=rows[Number(event.target.value)];
      this._scanSelectedIngredient=this._scanIngredientIdentity(row);
    });
    c.querySelectorAll("[data-scan-suggestion]").forEach(button=>button.addEventListener("click",()=>{
      this._scanSelectedIngredient=String(button.dataset.scanSuggestion||"");
      this._scanIngredientFilter="";
      const input=c.querySelector("#scanIngredientFilter");if(input)input.value="";
      this._renderScanIngredientOptions(c);
    }));
    c.querySelector("#scanMapAdd")?.addEventListener("click",async()=>{
      const result=this._scannerResult;if(!result?.barcode)return;
      const ingredient=this._selectedScanIngredient(c);
      if(!ingredient?.name){this._scannerStatus=this._t("invalidIngredient");this._renderScannerResult(c);return;}
      const quantity=String(c.querySelector("#scanPackageAmount")?.value||"").trim();
      const unit=String(c.querySelector("#scanPackageUnit")?.value||"").trim();
      if(!quantity)return;
      this._scannerBusy=true;this._scannerStatus=this._t("lookingUp");this._renderScannerResult(c);
      try{
        const mapped=await this._api("cook4me/v15/barcode_map_add",{
          entry_id:this._entryId,barcode:String(result.barcode),ingredient,
          quantity,unit,product_name:String(result.product?.productName||result.product?.name||""),brand:String(result.product?.brand||""),
        });
        this._houseIngredients=mapped?.houseIngredients||[];this._syncEntryProfile();this._renderInventoryOnly(c);
        this._scannerResult=mapped;this._scannerStatus=this._t("scannedAdded");navigator.vibrate?.(80);
        this._scanIngredientFilter="";this._scanSelectedIngredient="";
      }catch(e){this._scannerStatus=`${this._t("error")}: ${e.message||e}`;}
      finally{this._scannerBusy=false;this._renderScannerResult(c);}
      if(this._scannerOpen&&this._nativeBarcodeScannerAvailable()&&!this._nativeScannerActive){
        await this._startNativeBarcodeScanner(c);
      }
    });
  }

  async _handleBarcode(code,c){
    const previous=String(this._scannerResult?.barcode||"");
    await super._handleBarcode(code,c);
    if(this._scannerResult?.status!=="needs_mapping")return;
    if(String(this._scannerResult.barcode||"")!==previous){
      this._scanIngredientFilter="";
      const first=this._scanSuggestions()[0];
      this._scanSelectedIngredient=first?this._scanIngredientIdentity(first):"";
    }
    if(!this._ingredientCatalog?.length)void this._ensureScanCatalog(c);
    else this._renderScannerResult(c);
  }
}

customElements.define("cook4me-recipe-hub-panel-v19",Cook4MeRecipeHubPanelV19);

})();

// cook4me-panel-v20.js
(() => {

const BasePanel = customElements.get("cook4me-recipe-hub-panel-v19");

const TEXT = {
  en:{bestBefore:"Best before",bestBeforeHelp:"Optional. When restocking the same ingredient, the earliest known date is kept."},
  de:{bestBefore:"Mindestens haltbar bis",bestBeforeHelp:"Optional. Beim Nachfüllen derselben Zutat bleibt das früheste bekannte Datum erhalten."},
  el:{bestBefore:"Ανάλωση κατά προτίμηση πριν από",bestBeforeHelp:"Προαιρετικό. Σε νέα προσθήκη του ίδιου υλικού διατηρείται η νωρίτερη γνωστή ημερομηνία."},
};

class Cook4MeRecipeHubPanelV20 extends BasePanel {
  _t(key){return TEXT[this._langCode()]?.[key]||TEXT.en[key]||super._t(key);}

  _stockText(row){
    const base=super._stockText(row);
    return row?.bestBefore?`${base} · ${this._t("bestBefore")}: ${row.bestBefore}`:base;
  }

  _inventoryRowsHtml(){
    if(!this._houseIngredients.length)return `<div class="muted">${this._escape(this._t("houseEmpty"))}</div>`;
    return this._houseIngredients.map((row,index)=>{
      const unlimited=Boolean(row.unlimited);
      const amount=row.quantity===undefined||row.quantity===null?"":row.quantity;
      return `<div data-stock-row="${index}" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:8px;align-items:end;padding:10px 0;border-bottom:1px solid var(--divider-color)">
        <div style="min-width:180px"><strong>${this._escape(row.name||"")}</strong> <span class="muted">(${this._escape(this._stockText(row))})</span></div>
        <div class="field"><label>${this._escape(this._t("amount"))}</label><input data-stock-amount type="number" min="0" step="any" value="${this._escape(amount)}" ${unlimited?"disabled":""}></div>
        <div class="field"><label>${this._escape(this._t("unit"))}</label><input data-stock-unit value="${this._escape(row.unit||"")}" list="cook4meStockUnits"></div>
        <div class="field"><label>${this._escape(this._t("bestBefore"))}</label><input data-stock-best-before type="date" value="${this._escape(row.bestBefore||"")}"></div>
        <label style="display:flex;align-items:center;gap:6px;min-height:42px"><input data-stock-unlimited type="checkbox" ${unlimited?"checked":""}> ${this._escape(this._t("unlimited"))}</label>
        <div style="display:flex;gap:6px"><button class="btn secondary" data-stock-save>${this._escape(this._t("updateStock"))}</button><button class="btn secondary" data-stock-remove>${this._escape(this._t("removeStock"))}</button></div>
      </div>`;
    }).join("");
  }

  _bindInventoryRows(c){
    c.querySelectorAll("[data-stock-row]").forEach(container=>{
      const index=Number(container.dataset.stockRow); const row=this._houseIngredients[index]; if(!row)return;
      const unlimited=container.querySelector("[data-stock-unlimited]");
      const amount=container.querySelector("[data-stock-amount]");
      unlimited?.addEventListener("change",()=>{if(amount)amount.disabled=Boolean(unlimited.checked);});
      container.querySelector("[data-stock-save]")?.addEventListener("click",async()=>{
        try{
          const result=await this._api("cook4me/v14/inventory_update",{
            entry_id:this._entryId,
            identity:this._stockIdentity(row),
            ...(amount?.value!==""?{quantity:amount.value}:{}),
            unit:String(container.querySelector("[data-stock-unit]")?.value||""),
            unlimited:Boolean(unlimited?.checked),
            best_before:String(container.querySelector("[data-stock-best-before]")?.value||""),
          });
          this._houseIngredients=result?.houseIngredients||[];
          this._syncEntryProfile();
          this._renderInventoryOnly(c);
          this._message(this._t("stockUpdated"));
        }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
      });
      container.querySelector("[data-stock-remove]")?.addEventListener("click",async()=>{
        try{
          const result=await this._api("cook4me/v14/inventory_remove",{entry_id:this._entryId,identity:this._stockIdentity(row)});
          this._houseIngredients=result?.houseIngredients||[];
          this._syncEntryProfile();
          this._renderInventoryOnly(c);
          this._message(this._t("stockUpdated"));
        }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
      });
    });
  }

  _renderProfile(c){
    super._renderProfile(c);
    const unlimited=c.querySelector("#stockAddUnlimited");
    const unlimitedField=unlimited?.closest(".field");
    if(unlimitedField&&!c.querySelector("#stockAddBestBefore")){
      const dateField=document.createElement("div");
      dateField.className="field";
      dateField.innerHTML=`<label>${this._escape(this._t("bestBefore"))}</label><input id="stockAddBestBefore" type="date"><div class="muted">${this._escape(this._t("bestBeforeHelp"))}</div>`;
      unlimitedField.parentNode?.insertBefore(dateField,unlimitedField);
    }

    // Replace the v16 add button to remove its amount-only listener, while
    // preserving every other profile/scanner binding installed by the base UI.
    const oldButton=c.querySelector("#houseAdd");
    if(!oldButton)return;
    const button=oldButton.cloneNode(true);
    oldButton.replaceWith(button);
    const amount=c.querySelector("#stockAddAmount");
    button.addEventListener("click",async()=>{
      const select=c.querySelector("#houseCatalog");
      const rows=select?._cook4meRows||[];
      const row=rows[Number(select?.value)];
      if(!row)return;
      const scrollTop=select.scrollTop;
      const selectedValue=select.value;
      try{
        const result=await this._api("cook4me/v14/inventory_add",{
          entry_id:this._entryId,
          ingredient:row,
          ...(amount?.value!==""?{quantity:amount.value}:{}),
          unit:String(c.querySelector("#stockAddUnit")?.value||""),
          unlimited:Boolean(unlimited?.checked),
          best_before:String(c.querySelector("#stockAddBestBefore")?.value||""),
        });
        this._houseIngredients=result?.houseIngredients||[];
        this._syncEntryProfile();
        this._renderInventoryOnly(c);
        select.value=selectedValue;
        select.scrollTop=scrollTop;
        if(amount)amount.value="";
        const bestBefore=c.querySelector("#stockAddBestBefore");if(bestBefore)bestBefore.value="";
        this._message(this._t("stockUpdated"));
      }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
    });
  }

  _scannerResultHtml(){
    const html=super._scannerResultHtml();
    if(this._scannerResult?.status!=="needs_mapping")return html;
    const marker='<button id="scanMapAdd"';
    const pos=html.indexOf(marker);
    if(pos<0)return html;
    const dateField=`<div class="field" style="margin-top:10px"><label>${this._escape(this._t("bestBefore"))}</label><input id="scanBestBefore" type="date"><div class="muted">${this._escape(this._t("bestBeforeHelp"))}</div></div>`;
    return `${html.slice(0,pos)}${dateField}${html.slice(pos)}`;
  }

  _bindScannerMapping(c){
    // Let v19 bind search, suggestions and selector behavior first.
    super._bindScannerMapping(c);
    const oldButton=c.querySelector("#scanMapAdd");
    if(!oldButton)return;
    const button=oldButton.cloneNode(true);
    oldButton.replaceWith(button);
    button.addEventListener("click",async()=>{
      const result=this._scannerResult;if(!result?.barcode)return;
      const ingredient=this._selectedScanIngredient(c);
      if(!ingredient?.name){this._scannerStatus=this._t("invalidIngredient");this._renderScannerResult(c);return;}
      const quantity=String(c.querySelector("#scanPackageAmount")?.value||"").trim();
      const unit=String(c.querySelector("#scanPackageUnit")?.value||"").trim();
      const bestBefore=String(c.querySelector("#scanBestBefore")?.value||"");
      if(!quantity)return;
      this._scannerBusy=true;
      this._scannerStatus=this._t("lookingUp");
      this._renderScannerResult(c);
      try{
        const mapped=await this._api("cook4me/v15/barcode_map_add",{
          entry_id:this._entryId,
          barcode:String(result.barcode),
          ingredient,
          quantity,
          unit,
          best_before:bestBefore,
          product_name:String(result.product?.productName||result.product?.name||""),
          brand:String(result.product?.brand||""),
        });
        this._houseIngredients=mapped?.houseIngredients||[];
        this._syncEntryProfile();
        this._renderInventoryOnly(c);
        this._scannerResult=mapped;
        this._scannerStatus=this._t("scannedAdded");
        navigator.vibrate?.(80);
        this._scanIngredientFilter="";
        this._scanSelectedIngredient="";
      }catch(e){this._scannerStatus=`${this._t("error")}: ${e.message||e}`;}
      finally{this._scannerBusy=false;this._renderScannerResult(c);}
      if(this._scannerOpen&&this._nativeBarcodeScannerAvailable()&&!this._nativeScannerActive){
        await this._startNativeBarcodeScanner(c);
      }
    });
  }
}

customElements.define("cook4me-recipe-hub-panel-v20",Cook4MeRecipeHubPanelV20);

})();

// cook4me-panel-v21.js
(() => {

const BasePanel = customElements.get("cook4me-recipe-hub-panel-v20");

const TEXT = {
  en:{interfaceLanguage:"Interface language",automaticUiLanguage:"Automatic (Home Assistant)",uiLanguageHelp:"Changes only the Cook4Me interface language."},
  de:{interfaceLanguage:"Oberflächensprache",automaticUiLanguage:"Automatisch (Home Assistant)",uiLanguageHelp:"Ändert nur die Sprache der Cook4Me-Oberfläche."},
  el:{interfaceLanguage:"Γλώσσα περιβάλλοντος",automaticUiLanguage:"Αυτόματα (Home Assistant)",uiLanguageHelp:"Αλλάζει μόνο τη γλώσσα του περιβάλλοντος Cook4Me."},
};

const UI_LANGUAGES = new Set(["auto","en","de","el"]);

class Cook4MeRecipeHubPanelV21 extends BasePanel {
  constructor(){
    super();
    this._uiLanguage="auto";
    this._uiLanguageStorageKeyLoaded="";
  }

  _haLangCode(){
    return String(this._hass?.language||"en").toLowerCase().split(/[-_]/)[0]||"en";
  }

  _uiLanguageStorageKey(){
    const user=String(this._hass?.user?.id||this._hass?.user?.name||"default");
    return `cook4me.recipeHub.uiLanguage.${user}`;
  }

  _ensureUiLanguage(){
    const key=this._uiLanguageStorageKey();
    if(this._uiLanguageStorageKeyLoaded===key)return;
    let selected="auto";
    try{selected=String(globalThis.localStorage?.getItem(key)||"auto").toLowerCase();}catch(_e){}
    this._uiLanguage=UI_LANGUAGES.has(selected)?selected:"auto";
    this._uiLanguageStorageKeyLoaded=key;
  }

  _langCode(){
    this._ensureUiLanguage();
    if(this._uiLanguage!=="auto")return this._uiLanguage;
    const ha=this._haLangCode();
    return ["en","de","el"].includes(ha)?ha:"en";
  }

  _t(key){return TEXT[this._langCode()]?.[key]||TEXT.en[key]||super._t(key);}

  _saveUiLanguage(value){
    this._uiLanguage=UI_LANGUAGES.has(value)?value:"auto";
    try{globalThis.localStorage?.setItem(this._uiLanguageStorageKey(),this._uiLanguage);}catch(_e){}
  }

  _uiLanguageOptions(){
    const selected=this._uiLanguage;
    const options=[
      ["auto",this._t("automaticUiLanguage")],
      ["en",this._languageName("en")],
      ["de",this._languageName("de")],
      ["el",this._languageName("el")],
    ];
    return options.map(([value,label])=>`<option value="${this._escape(value)}" ${selected===value?"selected":""}>${this._escape(label)}</option>`).join("");
  }

  _renderUiLanguageControl(){
    this._ensureUiLanguage();
    const tabs=this.shadowRoot?.getElementById("tabs");
    if(!tabs?.parentNode)return;
    this.shadowRoot?.getElementById("cook4meUiLanguageControl")?.remove();
    const wrapper=document.createElement("div");
    wrapper.id="cook4meUiLanguageControl";
    wrapper.className="toolbar";
    wrapper.style.cssText="justify-content:flex-end;align-items:end;margin:12px 0 -6px";
    wrapper.innerHTML=`<div class="field" style="min-width:230px;max-width:340px"><label>${this._escape(this._t("interfaceLanguage"))}</label><select id="cook4meUiLanguage">${this._uiLanguageOptions()}</select><div class="muted">${this._escape(this._t("uiLanguageHelp"))}</div></div>`;
    tabs.parentNode.insertBefore(wrapper,tabs);
    wrapper.querySelector("#cook4meUiLanguage")?.addEventListener("change",event=>{
      this._saveUiLanguage(String(event.target.value||"auto").toLowerCase());
      this._updateHeader?.();
      this._renderTabs();
      this._renderTab();
    });
  }

  _renderTabs(){
    super._renderTabs();
    this._renderUiLanguageControl();
  }

  // The interface language is deliberately independent from recipe translation.
  // "Translate to Home Assistant language" must continue targeting HA's language.
  _translationNeeded(recipe){
    const source=this._recipeLanguage(recipe)||String(recipe?.sourceLanguage||"").toLowerCase().split(/[-_]/)[0];
    return Boolean(source&&source!==this._haLangCode());
  }

  _applyTranslation(recipe,row){
    const applied=super._applyTranslation(recipe,row);
    if(applied)recipe.language=this._haLangCode();
    return applied;
  }

  async _translateItems(items){
    if(!this._shouldTranslate())return;
    const pending=(items||[]).filter(recipe=>this._translationNeeded(recipe));
    if(!pending.length)return;
    for(let offset=0;offset<pending.length;offset+=20){
      const chunk=pending.slice(offset,offset+20);
      try{
        const result=await this._api("cook4me/v7/translate",{
          entry_id:this._entryId,
          target_language:this._haLangCode(),
          recipes:chunk,
        });
        if(!result?.available){this._translateEnabled=false;return;}
        const byId=new Map((result.items||[]).map(row=>[String(row?.id),row]));
        chunk.forEach((recipe,index)=>{
          const row=byId.get(String(index));
          if(row)this._applyTranslation(recipe,row);
        });
      }catch(_e){return;}
    }
  }

  async _translateSingle(recipe){
    if(!this._shouldTranslate()||!this._translationNeeded(recipe))return recipe;
    try{
      const result=await this._api("cook4me/v7/translate",{
        entry_id:this._entryId,
        target_language:this._haLangCode(),
        recipes:[recipe],
      });
      const row=result?.items?.find(item=>String(item?.id)==="0");
      if(result?.available&&row)this._applyTranslation(recipe,row);
    }catch(_e){}
    return recipe;
  }
}

customElements.define("cook4me-recipe-hub-panel-v21",Cook4MeRecipeHubPanelV21);

})();

// cook4me-panel-v22.js
(() => {

const BasePanel = customElements.get("cook4me-recipe-hub-panel-v21");

const TEXT = {
  en:{
    batches:"Stock batches",batch:"Batch",addBatch:"Add batch",removeBatch:"Remove batch",
    nextBestBefore:"Next best before",batchHelp:"Amounts keep their own best-before dates. Recipe consumption uses the earliest-expiring batch first, then automatically advances to the next date.",
    totalStock:"Total stock",undated:"No best-before date",
  },
  de:{
    batches:"Vorratschargen",batch:"Charge",addBatch:"Charge hinzufügen",removeBatch:"Charge entfernen",
    nextBestBefore:"Nächstes MHD",batchHelp:"Jede Menge behält ihr eigenes MHD. Beim Rezeptverbrauch wird zuerst die Charge mit dem frühesten MHD abgezogen; danach wird automatisch das nächste Datum aktiv.",
    totalStock:"Gesamtvorrat",undated:"Kein MHD",
  },
  el:{
    batches:"Παρτίδες αποθέματος",batch:"Παρτίδα",addBatch:"Προσθήκη παρτίδας",removeBatch:"Αφαίρεση παρτίδας",
    nextBestBefore:"Επόμενη ανάλωση κατά προτίμηση",batchHelp:"Κάθε ποσότητα κρατά τη δική της ημερομηνία. Η κατανάλωση συνταγής αφαιρεί πρώτα την παρτίδα που λήγει νωρίτερα και μετά περνά αυτόματα στην επόμενη ημερομηνία.",
    totalStock:"Συνολικό απόθεμα",undated:"Χωρίς ημερομηνία",
  },
};

class Cook4MeRecipeHubPanelV22 extends BasePanel {
  _t(key){return TEXT[this._langCode()]?.[key]||TEXT.en[key]||super._t(key);}

  _shownNumber(value){
    const number=Number(value);
    if(!Number.isFinite(number))return String(value??"");
    return Number.isInteger(number)?String(number):String(Number(number.toFixed(9)));
  }

  _rowLots(row){
    if(Array.isArray(row?.lots)&&row.lots.length)return row.lots.map(lot=>({...lot}));
    if(row?.quantity!==undefined&&row?.quantity!==null&&row?.quantity!==""){
      return [{quantity:row.quantity,...(row.bestBefore?{bestBefore:row.bestBefore}:{})}];
    }
    return [];
  }

  _stockText(row){
    if(row?.unlimited){
      return row?.bestBefore?`∞ · ${this._t("nextBestBefore")}: ${row.bestBefore}`:"∞";
    }
    const amount=row?.quantity===undefined||row?.quantity===null?this._t("stockUnknown"):this._shownNumber(row.quantity);
    const total=`${amount}${row?.unit?` ${row.unit}`:""}`;
    return row?.bestBefore?`${total} · ${this._t("nextBestBefore")}: ${row.bestBefore}`:total;
  }

  _lotRowHtml(lot,index,unit){
    const amount=lot?.quantity===undefined||lot?.quantity===null?"":lot.quantity;
    return `<div data-stock-lot="${index}" style="display:grid;grid-template-columns:minmax(110px,1fr) minmax(150px,1fr) auto;gap:8px;align-items:end;padding:7px 0">
      <div class="field"><label>${this._escape(this._t("amount"))}${unit?` (${this._escape(unit)})`:""}</label><input data-stock-lot-amount type="number" min="0" step="any" value="${this._escape(amount)}"></div>
      <div class="field"><label>${this._escape(this._t("bestBefore"))}</label><input data-stock-lot-date type="date" value="${this._escape(lot?.bestBefore||"")}"></div>
      <button type="button" class="btn secondary" data-stock-lot-remove style="min-height:42px">${this._escape(this._t("removeBatch"))}</button>
    </div>`;
  }

  _inventoryRowsHtml(){
    if(!this._houseIngredients.length)return `<div class="muted">${this._escape(this._t("houseEmpty"))}</div>`;
    return this._houseIngredients.map((row,index)=>{
      const unlimited=Boolean(row.unlimited);
      const lots=this._rowLots(row);
      const lotsHtml=lots.map((lot,lotIndex)=>this._lotRowHtml(lot,lotIndex,row.unit||"")).join("");
      return `<div data-stock-row="${index}" style="padding:12px 0;border-bottom:1px solid var(--divider-color)">
        <div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap">
          <div><strong>${this._escape(row.name||"")}</strong><div class="muted">${this._escape(this._t("totalStock"))}: ${this._escape(this._stockText(row))}</div></div>
          <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:end">
            <div class="field" style="min-width:100px"><label>${this._escape(this._t("unit"))}</label><input data-stock-unit value="${this._escape(row.unit||"")}" list="cook4meStockUnits"></div>
            ${unlimited?`<div class="field" style="min-width:160px"><label>${this._escape(this._t("bestBefore"))}</label><input data-stock-unlimited-date type="date" value="${this._escape(row.bestBefore||"")}"></div>`:""}
            <label style="display:flex;align-items:center;gap:6px;min-height:42px"><input data-stock-unlimited type="checkbox" ${unlimited?"checked":""}> ${this._escape(this._t("unlimited"))}</label>
          </div>
        </div>
        <div data-stock-lots-wrap style="margin-top:10px;${unlimited?"display:none":""}">
          <div><strong>${this._escape(this._t("batches"))}</strong></div>
          <div class="muted" style="margin:3px 0 6px">${this._escape(this._t("batchHelp"))}</div>
          <div data-stock-lots>${lotsHtml}</div>
          <button type="button" class="btn secondary" data-stock-lot-add style="margin-top:6px">+ ${this._escape(this._t("addBatch"))}</button>
        </div>
        <div style="display:flex;gap:6px;margin-top:10px;flex-wrap:wrap"><button class="btn secondary" data-stock-save>${this._escape(this._t("updateStock"))}</button><button class="btn secondary" data-stock-remove>${this._escape(this._t("removeStock"))}</button></div>
      </div>`;
    }).join("");
  }

  _appendLotRow(container,row){
    const holder=container.querySelector("[data-stock-lots]");
    if(!holder)return;
    const index=holder.querySelectorAll("[data-stock-lot]").length;
    holder.insertAdjacentHTML("beforeend",this._lotRowHtml({},index,row?.unit||""));
    this._bindLotRemoveButtons(container);
  }

  _bindLotRemoveButtons(container){
    container.querySelectorAll("[data-stock-lot-remove]").forEach(button=>{
      if(button.dataset.cook4meBound)return;
      button.dataset.cook4meBound="1";
      button.addEventListener("click",()=>button.closest("[data-stock-lot]")?.remove());
    });
  }

  _collectLots(container,row,newUnit){
    const sourceUnit=String(row?.unit||newUnit||"");
    const lots=[];
    container.querySelectorAll("[data-stock-lot]").forEach(lotEl=>{
      const raw=String(lotEl.querySelector("[data-stock-lot-amount]")?.value||"").trim();
      if(!raw)return;
      const amount=Number(raw.replace(",","."));
      if(!Number.isFinite(amount)||amount<=0)return;
      const bestBefore=String(lotEl.querySelector("[data-stock-lot-date]")?.value||"");
      lots.push({quantity:raw,unit:sourceUnit,...(bestBefore?{bestBefore}: {})});
    });
    return lots;
  }

  _bindInventoryRows(c){
    c.querySelectorAll("[data-stock-row]").forEach(container=>{
      const index=Number(container.dataset.stockRow);
      const row=this._houseIngredients[index];
      if(!row)return;
      const unlimited=container.querySelector("[data-stock-unlimited]");
      const lotsWrap=container.querySelector("[data-stock-lots-wrap]");
      unlimited?.addEventListener("change",()=>{
        if(lotsWrap)lotsWrap.style.display=unlimited.checked?"none":"";
      });
      this._bindLotRemoveButtons(container);
      container.querySelector("[data-stock-lot-add]")?.addEventListener("click",()=>this._appendLotRow(container,row));

      container.querySelector("[data-stock-save]")?.addEventListener("click",async()=>{
        try{
          const unit=String(container.querySelector("[data-stock-unit]")?.value||"");
          const isUnlimited=Boolean(unlimited?.checked);
          if(!isUnlimited){
            const lots=this._collectLots(container,row,unit);
            if(!lots.length){
              const result=await this._api("cook4me/v14/inventory_remove",{entry_id:this._entryId,identity:this._stockIdentity(row)});
              this._houseIngredients=result?.houseIngredients||[];
              this._syncEntryProfile();
              this._renderInventoryOnly(c);
              this._message(this._t("stockUpdated"));
              return;
            }
            const result=await this._api("cook4me/v14/inventory_update",{
              entry_id:this._entryId,
              identity:this._stockIdentity(row),
              unit,
              unlimited:false,
              lots,
            });
            this._houseIngredients=result?.houseIngredients||[];
          }else{
            const result=await this._api("cook4me/v14/inventory_update",{
              entry_id:this._entryId,
              identity:this._stockIdentity(row),
              unit,
              unlimited:true,
              best_before:String(container.querySelector("[data-stock-unlimited-date]")?.value||row.bestBefore||""),
            });
            this._houseIngredients=result?.houseIngredients||[];
          }
          this._syncEntryProfile();
          this._renderInventoryOnly(c);
          this._message(this._t("stockUpdated"));
        }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
      });

      container.querySelector("[data-stock-remove]")?.addEventListener("click",async()=>{
        try{
          const result=await this._api("cook4me/v14/inventory_remove",{entry_id:this._entryId,identity:this._stockIdentity(row)});
          this._houseIngredients=result?.houseIngredients||[];
          this._syncEntryProfile();
          this._renderInventoryOnly(c);
          this._message(this._t("stockUpdated"));
        }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
      });
    });
  }
}

customElements.define("cook4me-recipe-hub-panel-v22",Cook4MeRecipeHubPanelV22);

})();

// cook4me-panel-v23.js
(() => {

const BasePanel = customElements.get("cook4me-recipe-hub-panel-v22");

const TEXT = {
  en:{
    nutrition:"Nutrition",wholeMeal:"Whole meal",perServingNutrition:"Per serving",calories:"Calories",protein:"Protein",carbs:"Carbs",fat:"Fat",fiber:"Fibre",sugars:"Sugars",saturatedFat:"Saturated fat",salt:"Salt",
    nutritionCoverage:"Nutrition coverage",nutritionEstimate:"Estimate",nutritionExact:"Uses scanned product nutrition",nutritionLoading:"Calculating nutrition…",nutritionUnavailable:"Not enough nutrition data to calculate this meal yet.",
    nutritionSettings:"Nutrition catalog",fdcApiKey:"USDA FoodData Central API key",fdcHelp:"Optional. Without your own key Cook4Me uses USDA DEMO_KEY with low rate limits. A personal key lets the generic nutrition catalog build much faster.",
    saveApiKey:"Save API key",clearApiKey:"Clear API key",apiKeyConfigured:"Personal USDA API key configured",demoKeyMode:"Using USDA DEMO_KEY",buildCatalog:"Build next nutrition catalog batch",catalogMapped:"generic ingredients mapped",catalogRemaining:"remaining",scannedNutrition:"Nutrition captured from scanned product",
  },
  de:{
    nutrition:"Nährwerte",wholeMeal:"Gesamtes Gericht",perServingNutrition:"Pro Portion",calories:"Kalorien",protein:"Eiweiß",carbs:"Kohlenhydrate",fat:"Fett",fiber:"Ballaststoffe",sugars:"Zucker",saturatedFat:"Gesättigte Fettsäuren",salt:"Salz",
    nutritionCoverage:"Nährwert-Abdeckung",nutritionEstimate:"Schätzung",nutritionExact:"Verwendet Nährwerte gescannter Produkte",nutritionLoading:"Nährwerte werden berechnet…",nutritionUnavailable:"Noch nicht genug Nährwertdaten für dieses Gericht.",
    nutritionSettings:"Nährwertkatalog",fdcApiKey:"USDA FoodData Central API-Schlüssel",fdcHelp:"Optional. Ohne eigenen Schlüssel nutzt Cook4Me den USDA-DEMO_KEY mit niedrigen Limits. Mit einem persönlichen Schlüssel kann der generische Nährwertkatalog deutlich schneller aufgebaut werden.",
    saveApiKey:"API-Schlüssel speichern",clearApiKey:"API-Schlüssel löschen",apiKeyConfigured:"Persönlicher USDA-API-Schlüssel eingerichtet",demoKeyMode:"USDA DEMO_KEY wird verwendet",buildCatalog:"Nächsten Nährwert-Katalogblock aufbauen",catalogMapped:"generische Zutaten zugeordnet",catalogRemaining:"verbleibend",scannedNutrition:"Nährwerte vom gescannten Produkt übernommen",
  },
  el:{
    nutrition:"Διατροφικά στοιχεία",wholeMeal:"Ολόκληρο γεύμα",perServingNutrition:"Ανά μερίδα",calories:"Θερμίδες",protein:"Πρωτεΐνη",carbs:"Υδατάνθρακες",fat:"Λιπαρά",fiber:"Φυτικές ίνες",sugars:"Σάκχαρα",saturatedFat:"Κορεσμένα λιπαρά",salt:"Αλάτι",
    nutritionCoverage:"Κάλυψη διατροφικών στοιχείων",nutritionEstimate:"Εκτίμηση",nutritionExact:"Χρησιμοποιεί στοιχεία από σαρωμένα προϊόντα",nutritionLoading:"Υπολογισμός διατροφικών στοιχείων…",nutritionUnavailable:"Δεν υπάρχουν ακόμη αρκετά διατροφικά δεδομένα για αυτό το γεύμα.",
    nutritionSettings:"Κατάλογος διατροφικών στοιχείων",fdcApiKey:"Κλειδί API USDA FoodData Central",fdcHelp:"Προαιρετικό. Χωρίς προσωπικό κλειδί το Cook4Me χρησιμοποιεί το USDA DEMO_KEY με χαμηλά όρια. Με προσωπικό κλειδί ο γενικός κατάλογος διατροφής δημιουργείται πολύ γρηγορότερα.",
    saveApiKey:"Αποθήκευση κλειδιού API",clearApiKey:"Διαγραφή κλειδιού API",apiKeyConfigured:"Έχει ρυθμιστεί προσωπικό κλειδί USDA API",demoKeyMode:"Χρήση USDA DEMO_KEY",buildCatalog:"Δημιουργία επόμενης παρτίδας καταλόγου",catalogMapped:"γενικά υλικά αντιστοιχισμένα",catalogRemaining:"απομένουν",scannedNutrition:"Τα διατροφικά στοιχεία λήφθηκαν από το σαρωμένο προϊόν",
  },
};

class Cook4MeRecipeHubPanelV23 extends BasePanel {
  constructor(){
    super();
    this._nutritionSettings=null;
    this._nutritionSettingsLoading=false;
    this._nutritionBusy=new Set();
  }

  _t(key){return TEXT[this._langCode()]?.[key]||TEXT.en[key]||super._t(key);}

  _nutritionRecipePayload(recipe){
    return {
      title:recipe?.title||"",
      servings:recipe?.servings,
      groupSize:recipe?.groupSize,
      yield:recipe?.yield,
      ingredients:Array.isArray(recipe?._nutritionIngredients)?recipe._nutritionIngredients:(recipe?.ingredients||[]),
    };
  }

  _applyTranslation(recipe,row){
    if(!Array.isArray(recipe?._nutritionIngredients)&&Array.isArray(recipe?.ingredients)&&recipe.ingredients.some(item=>item&&typeof item==="object")){
      recipe._nutritionIngredients=recipe.ingredients.map(item=>item&&typeof item==="object"?{...item}:item);
    }
    return super._applyTranslation(recipe,row);
  }

  _metric(value,key,unit="g"){
    const number=Number(value);
    if(!Number.isFinite(number))return"";
    const shown=key==="energyKcal"?Math.round(number):Number(number.toFixed(1));
    return `${shown}${unit?` ${unit}`:""}`;
  }

  _nutritionChips(values,compact=false){
    if(!values||typeof values!=="object")return"";
    const rows=[
      ["energyKcal",this._t("calories"),"kcal"],
      ["protein",this._t("protein"),"g"],
      ["carbohydrates",this._t("carbs"),"g"],
      ["fat",this._t("fat"),"g"],
      ...(!compact?[["fiber",this._t("fiber"),"g"],["sugars",this._t("sugars"),"g"],["saturatedFat",this._t("saturatedFat"),"g"],["salt",this._t("salt"),"g"]]:[]),
    ];
    return rows.filter(([key])=>Number.isFinite(Number(values[key]))).map(([key,label,unit])=>`<span class="chip">${this._escape(label)}: ${this._escape(this._metric(values[key],key,unit))}</span>`).join("");
  }

  _nutritionBlock(nutrition){
    if(!nutrition||!nutrition.totals||!Object.keys(nutrition.totals).length)return `<section class="card" style="margin:12px 0"><h3 style="margin-top:0">${this._escape(this._t("nutrition"))}</h3><div class="muted">${this._escape(this._t("nutritionUnavailable"))}</div></section>`;
    const coverage=Math.round(Number(nutrition.coverage||0)*100);
    const exact=(nutrition.sourceKinds||[]).includes("exact_product");
    return `<section class="card" style="margin:12px 0">
      <h3 style="margin-top:0">${this._escape(this._t("nutrition"))}</h3>
      <div class="muted" style="margin-bottom:7px">${this._escape(this._t("nutritionCoverage"))}: ${coverage}%${nutrition.estimated?` · ${this._escape(this._t("nutritionEstimate"))}`:""}${exact?` · ${this._escape(this._t("nutritionExact"))}`:""}</div>
      <div><strong>${this._escape(this._t("wholeMeal"))}</strong><div class="chips" style="margin-top:6px">${this._nutritionChips(nutrition.totals,false)}</div></div>
      ${nutrition.perServing&&Object.keys(nutrition.perServing).length?`<div style="margin-top:10px"><strong>${this._escape(this._t("perServingNutrition"))}${nutrition.servings?` (${this._escape(nutrition.servings)})`:""}</strong><div class="chips" style="margin-top:6px">${this._nutritionChips(nutrition.perServing,false)}</div></div>`:""}
    </section>`;
  }

  async _fetchNutrition(recipe,resolveMissing){
    if(!this._entryId||!recipe)return null;
    const key=this._recipeKey?this._recipeKey(recipe):String(recipe?.title||"recipe");
    if(this._nutritionBusy.has(key))return null;
    this._nutritionBusy.add(key);
    try{
      const result=await this._api("cook4me/v16/nutrition_recipe",{
        entry_id:this._entryId,
        recipe:this._nutritionRecipePayload(recipe),
        resolve_missing:Boolean(resolveMissing),
        max_resolve:8,
      });
      if(result?.nutrition)recipe.nutrition=result.nutrition;
      if(result){
        this._nutritionSettings={...(this._nutritionSettings||{}),catalogCount:result.catalogCount??this._nutritionSettings?.catalogCount,fdcApiKeyConfigured:Boolean(result.fdcApiKeyConfigured),fdcMode:result.fdcMode||this._nutritionSettings?.fdcMode};
      }
      return result;
    }catch(_e){return null;}
    finally{this._nutritionBusy.delete(key);}
  }

  async _loadRecipeNutrition(recipe,resolveMissing=true){
    const key=this._recipeKey?this._recipeKey(recipe):String(recipe?.title||"recipe");
    this._nutritionBusy.add(`ui:${key}`);
    this._renderTab();
    await this._fetchNutrition(recipe,resolveMissing);
    this._nutritionBusy.delete(`ui:${key}`);
    if(this._opened&&recipe!==this._opened&&this._recipeKey&&this._recipeKey(this._opened)===key)this._opened.nutrition=recipe.nutrition;
    this._renderTab();
  }

  async _hydrateVisibleNutrition(items){
    const rows=(items||[]).slice(0,12);
    if(!rows.length)return;
    await Promise.allSettled(rows.map(recipe=>this._fetchNutrition(recipe,false)));
    if(this._tab==="official"||this._tab==="recommend")this._renderTab();
  }

  async _search(query){
    await super._search(query);
    void this._hydrateVisibleNutrition(this._results||[]);
  }

  async _recommend(){
    await super._recommend();
    void this._hydrateVisibleNutrition(this._recommendations||[]);
  }

  async _openOfficial(recipe){
    await super._openOfficial(recipe);
    if(this._opened)await this._loadRecipeNutrition(this._opened,true);
  }

  async _openLocal(recipe){
    await super._openLocal(recipe);
    if(this._opened)await this._loadRecipeNutrition(this._opened,true);
  }

  _recipeCard(recipe,custom=false){
    let html=super._recipeCard(recipe,custom);
    const nutrition=recipe?.nutrition;
    if(nutrition?.totals&&Object.keys(nutrition.totals).length){
      const chips=this._nutritionChips(nutrition.perServing&&Object.keys(nutrition.perServing).length?nutrition.perServing:nutrition.totals,true);
      if(chips)html=html.replace('<div class="chips">',`<div class="chips">${chips}`);
    }
    return html;
  }

  _detailHtml(recipe){
    let html=super._detailHtml(recipe);
    if(!html||!recipe)return html;
    const key=this._recipeKey?this._recipeKey(recipe):String(recipe?.title||"recipe");
    const loading=this._nutritionBusy.has(`ui:${key}`);
    const block=loading?`<section class="card" style="margin:12px 0"><h3 style="margin-top:0">${this._escape(this._t("nutrition"))}</h3><div class="muted">${this._escape(this._t("nutritionLoading"))}</div></section>`:this._nutritionBlock(recipe.nutrition);
    const marker='<div class="detail-layout"';
    const pos=html.indexOf(marker);
    return pos>=0?`${html.slice(0,pos)}${block}${html.slice(pos)}`:`${block}${html}`;
  }

  _scannerResultHtml(){
    const html=super._scannerResultHtml();
    const nutrition=this._scannerResult?.product?.nutrition||this._scannerResult?.mapping?.nutrition;
    if(!nutrition?.values)return html;
    const block=`<div class="card" style="padding:10px;margin:8px 0"><strong>${this._escape(this._t("scannedNutrition"))}</strong><div class="chips" style="margin-top:6px">${this._nutritionChips(nutrition.values,false)}</div></div>`;
    return `${block}${html}`;
  }

  async _loadNutritionSettings(){
    if(this._nutritionSettingsLoading||!this._entryId)return;
    this._nutritionSettingsLoading=true;
    try{this._nutritionSettings=await this._api("cook4me/v16/nutrition_settings",{entry_id:this._entryId});}
    catch(_e){}
    finally{this._nutritionSettingsLoading=false;if(this._tab==="profile")this._renderTab();}
  }

  _nutritionSettingsHtml(){
    const s=this._nutritionSettings||{};
    const status=s.fdcApiKeyConfigured?this._t("apiKeyConfigured"):this._t("demoKeyMode");
    const count=Number(s.catalogCount||0);
    const total=Number(s.catalogTotal||0);
    return `<section class="card" style="margin-top:14px">
      <h2 style="margin-top:0">${this._escape(this._t("nutritionSettings"))}</h2>
      <div class="muted" style="margin-bottom:10px">${this._escape(this._t("fdcHelp"))}</div>
      <div class="formgrid">
        <div class="field wide"><label>${this._escape(this._t("fdcApiKey"))}</label><input id="fdcApiKey" type="password" autocomplete="off" placeholder="${this._escape(status)}"></div>
        <div class="field wide"><div class="toolbar"><button id="saveFdcApiKey" type="button" class="btn secondary">${this._escape(this._t("saveApiKey"))}</button>${s.fdcApiKeyConfigured?`<button id="clearFdcApiKey" type="button" class="btn secondary">${this._escape(this._t("clearApiKey"))}</button>`:""}<button id="buildNutritionCatalog" type="button" class="btn secondary">${this._escape(this._t("buildCatalog"))}</button></div></div>
      </div>
      <div id="nutritionCatalogStatus" class="muted" style="margin-top:8px">${this._escape(status)} · ${count} ${this._escape(this._t("catalogMapped"))}${total?` / ${total}`:""}${Number.isFinite(Number(s.remaining))?` · ${s.remaining} ${this._escape(this._t("catalogRemaining"))}`:""}</div>
    </section>`;
  }

  _bindNutritionSettings(c){
    c.querySelector("#saveFdcApiKey")?.addEventListener("click",async()=>{
      const key=String(c.querySelector("#fdcApiKey")?.value||"").trim();
      if(!key)return;
      try{this._nutritionSettings=await this._api("cook4me/v16/nutrition_settings_set",{entry_id:this._entryId,api_key:key});this._renderProfile(c);}catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
    });
    c.querySelector("#clearFdcApiKey")?.addEventListener("click",async()=>{
      try{this._nutritionSettings=await this._api("cook4me/v16/nutrition_settings_set",{entry_id:this._entryId,api_key:""});this._renderProfile(c);}catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
    });
    c.querySelector("#buildNutritionCatalog")?.addEventListener("click",async()=>{
      const button=c.querySelector("#buildNutritionCatalog");if(button)button.disabled=true;
      try{
        const result=await this._api("cook4me/v16/nutrition_catalog_fill",{entry_id:this._entryId,limit:12});
        this._nutritionSettings={...(this._nutritionSettings||{}),...result};
        const status=c.querySelector("#nutritionCatalogStatus");
        if(status)status.textContent=`${result.catalogCount||0} ${this._t("catalogMapped")} / ${result.catalogTotal||0} · ${result.remaining||0} ${this._t("catalogRemaining")}`;
      }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
      finally{if(button)button.disabled=false;}
    });
  }

  _renderProfile(c){
    super._renderProfile(c);
    if(!this._nutritionSettings&&!this._nutritionSettingsLoading)queueMicrotask(()=>void this._loadNutritionSettings());
    c.insertAdjacentHTML("beforeend",this._nutritionSettingsHtml());
    this._bindNutritionSettings(c);
  }
}

customElements.define("cook4me-recipe-hub-panel-v23",Cook4MeRecipeHubPanelV23);

})();

