 async _loadOverview(silent=false,rerender=true){await super._loadOverview(silent,rerender);void this._loadBookState(true)}
 async _loadBookState(silent=false){if(this._bookLoading||!this._entryId)return;this._bookLoading=true;try{this._bookState=await this._api("cook4me/v19/book_state",{entry_id:this._entryId});this._updateHeader();if(this._tab==="book")this._renderTab()}catch(e){if(!silent)this._message(`${this._t("error")}: ${e.message||e}`,true)}finally{this._bookLoading=false}}
 _recipeKeyLocal(r){const v=String(r?.groupingFunctionalId||r?.sendGroupingFunctionalId||"").trim();if(v)return`g:${v}`;const id=String(r?.id||"").trim();if(id)return`local:${id}`;const rv=String(r?.recipeFunctionalId||r?.variantFunctionalId||r?.displayVariantId||r?.searchVariantId||"").trim();if(rv)return`r:${rv}`;return`title:${String(r?.language||r?.sourceLanguage||"").toLowerCase()}:${String(r?.title||"").trim().toLowerCase()}`}
