 _renderTab(){if(this._tab==="book"){const c=this.shadowRoot?.getElementById("content");if(c)this._renderBook(c);return}if(this._tab==="mine"){const c=this.shadowRoot?.getElementById("content");if(c)this._renderMineV28(c);return}if(this._tab==="ai"){const c=this.shadowRoot?.getElementById("content");if(c)this._renderAIV28(c);return}super._renderTab()}

 _updateHeader(){super._updateHeader();const el=this.shadowRoot?.getElementById("status");const q=this._bookState?.queuedSend;if(!el||!q)return;if(el.querySelector(".queue-banner"))return;el.insertAdjacentHTML("beforeend",`<div class="queue-banner"><strong>⏳ ${this._escape(this._t("queuedRecipe"))}:</strong> ${this._escape(q.title||q.variantId||"")}<div class="muted">${this._escape(q.reason||"")}</div><button id="headerQueueCancel" class="btn secondary" style="margin-top:7px;min-height:34px;padding:6px 9px">${this._escape(this._t("cancelQueue"))}</button></div>`);el.querySelector("#headerQueueCancel")?.addEventListener("click",()=>void this._clearSendQueue())}
 async _clearSendQueue(){try{await this._api("cook4me/v19/send_queue_clear",{entry_id:this._entryId});if(this._bookState)this._bookState.queuedSend=null;this._updateHeader();this._renderTab()}catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true)}}

 _processStart(title,detail=""){this._process?.overlay?.remove();const token={cancelled:false};const overlay=document.createElement("div");overlay.className="rx-overlay";overlay.innerHTML=`<div class="rx-dialog"><h2>⏳ ${this._escape(title||this._t("backgroundWork"))}</h2><div data-process-detail class="muted">${this._escape(detail)}</div><div class="rx-progress"><div></div></div><div class="toolbar"><button data-process-cancel class="btn secondary">${this._escape(this._t("cancelWork"))}</button></div></div>`;this.shadowRoot.appendChild(overlay);overlay.querySelector("[data-process-cancel]")?.addEventListener("click",()=>{token.cancelled=true;const d=overlay.querySelector("[data-process-detail]");if(d)d.textContent=this._t("cancelling");setTimeout(()=>overlay.remove(),180)});token.overlay=overlay;this._process=token;return token}
 _processUpdate(token,detail,done=null,total=null){if(!token||token.cancelled||!token.overlay?.isConnected)return;const d=token.overlay.querySelector("[data-process-detail]");if(d)d.textContent=String(detail||"");if(Number.isFinite(done)&&Number.isFinite(total)&&total>0){const p=token.overlay.querySelector(".rx-progress");p?.classList.add("determinate");const bar=p?.querySelector("div");if(bar)bar.style.width=`${Math.max(0,Math.min(100,Math.round(done/total*100)))}%`}}
 _processEnd(token){if(token?.overlay?.isConnected)token.overlay.remove();if(this._process===token)this._process=null}

 async _search(query){const p=this._processStart(this._t("backgroundWork"),this._t("searchingRecipes"));try{await super._search(query)}finally{this._processEnd(p)}}
