 _coverage(recipe,item){const key=String(item?.foodKey||item?.key||"");const name=this._ingredientName(item).trim().toLocaleLowerCase();for(const r of recipe?.match?.quantityAvailability||[]){if((key&&String(r?.key||"")===key)||String(r?.name||"").trim().toLocaleLowerCase()===name){const c=Number(r?.coverage);return{status:String(r?.status||"unknown"),percent:Number.isFinite(c)?Math.max(0,Math.min(100,Math.round(c*100))):null,row:r}}}for(const r of recipe?.match?.ingredientAvailability||[]){if((key&&String(r?.key||"")===key)||String(r?.name||"").trim().toLocaleLowerCase()===name){const st=String(r?.status||"unknown");return{status:st,percent:st==="at_home"||st==="staple"?100:st==="missing"?0:null,row:r}}}return{status:"unknown",percent:null,row:null}}
