// cook4me-panel-v40.js
(() => {

const BasePanel=customElements.get("cook4me-recipe-hub-panel-v39");

class Cook4MeRecipeHubPanelV40 extends BasePanel{
  _normalizeTodayActionIcon(button,icon,{iconOnly=false}={}){
    if(!button)return;

    // v34 renders its own <ha-icon>, while the inherited v30/v32 global
    // button modernizer also prepends an rx-leading-icon. Normalize the DOM to
    // the modernizer's contract before that queued pass runs so every Today
    // action can physically contain only one icon.
    for(const child of [...button.children]){
      if(String(child.tagName||"").toUpperCase()==="HA-ICON")child.remove();
    }

    const node=this._newIcon(icon,"rx-leading-icon");
    button.prepend(node);
    button.dataset.rxIcon=icon;

    if(iconOnly){
      for(const child of [...button.children]){
        if(child!==node)child.remove();
      }
      for(const text of [...button.childNodes]){
        if(text.nodeType===Node.TEXT_NODE)text.textContent="";
      }
    }
  }

  _normalizeTodayActionButtons(c){
    const suggest=c?.querySelector?.("#todaySuggest");
    const reset=c?.querySelector?.("#todayReset");
    this._normalizeTodayActionIcon(suggest,"chef-hat");
    this._normalizeTodayActionIcon(reset,"backup-restore",{iconOnly:true});
  }

  _modernizeButtons(root){
    super._modernizeButtons(root);
    const content=this.shadowRoot?.getElementById("content");
    if(content)this._normalizeTodayActionButtons(content);
  }

  _renderToday(c){
    super._renderToday(c);
    this._normalizeTodayActionButtons(c);
    queueMicrotask(()=>this._normalizeTodayActionButtons(c));
  }
}

customElements.define("cook4me-recipe-hub-panel-v40",Cook4MeRecipeHubPanelV40);

})();

// cook4me-panel-v41.js
(() => {

const BasePanel=customElements.get("cook4me-recipe-hub-panel-v40");
const VALID_SECTIONS=new Set(["today","official","recommend","book","mine","profile","shopping","ai"]);
const LAST_SECTION_PREFIX="cook4me.ui.lastSection.v1.";

class Cook4MeRecipeHubPanelV41 extends BasePanel{
  constructor(){
    super();
    this._restoredSectionUser="";
    this._outsidePointerHandler=event=>this._dismissOpenMenusFromPointer(event);
  }

  get hass(){return super.hass;}
  set hass(value){
    const user=String(value?.user?.id||"anonymous");
    if(user!==this._restoredSectionUser){
      this._restoredSectionUser=user;
      const saved=this._loadLastSection(user);
      if(saved)this._tab=saved;
    }
    super.hass=value;
  }

  connectedCallback(){
    super.connectedCallback();
    document.addEventListener("pointerdown",this._outsidePointerHandler,true);
  }

  disconnectedCallback(){
    document.removeEventListener("pointerdown",this._outsidePointerHandler,true);
    if(super.disconnectedCallback)super.disconnectedCallback();
  }

  _lastSectionKey(user=this._restoredSectionUser||String(this._hass?.user?.id||"anonymous")){
    return `${LAST_SECTION_PREFIX}${user}`;
  }

  _loadLastSection(user){
    try{
      const value=String(localStorage.getItem(this._lastSectionKey(user))||"");
      return VALID_SECTIONS.has(value)?value:"";
    }catch(_e){return"";}
  }

  _rememberSection(section){
    const value=String(section||"");
    if(!VALID_SECTIONS.has(value))return;
    try{localStorage.setItem(this._lastSectionKey(),value);}catch(_e){}
  }

  _renderTabs(){
    super._renderTabs();
    const tabs=this.shadowRoot?.getElementById("tabs");
    if(!tabs||tabs.dataset.cook4meRememberSection==="1")return;
    tabs.dataset.cook4meRememberSection="1";
    tabs.addEventListener("click",event=>{
      const target=event.target instanceof Element?event.target.closest("[data-tab]"):null;
      if(target&&tabs.contains(target))this._rememberSection(target.dataset.tab);
    },true);
  }

  _renderTab(){
    this._rememberSection(this._tab);
    return super._renderTab();
  }

  _dismissOpenMenusFromPointer(event){
    const root=this.shadowRoot;
    if(!root)return;
    const path=typeof event?.composedPath==="function"?event.composedPath():[];
    const selector="details.rx-today-picker[open],details.rx-advanced[open],details[data-menu][open],details[data-selector][open]";
    root.querySelectorAll(selector).forEach(menu=>{
      if(!path.includes(menu))menu.removeAttribute("open");
    });
  }
}

customElements.define("cook4me-recipe-hub-panel-v41",Cook4MeRecipeHubPanelV41);

})();

// cook4me-panel-v42.js
(() => {

const BasePanel=customElements.get("cook4me-recipe-hub-panel-v41");

const TEXT={
  en:{
    officialNutrition:"Official SEB nutrition",
    officialPer100g:"Per 100 g",
    officialNutritionHelp:"Official per-100-g values are kept separate from meal totals. Meal totals continue to use quantity-aware scanned-product and generic ingredient data.",
  },
  de:{
    officialNutrition:"Offizielle SEB-Nährwerte",
    officialPer100g:"Pro 100 g",
    officialNutritionHelp:"Offizielle Werte pro 100 g bleiben von den Gerichtssummen getrennt. Die Gerichtssummen verwenden weiterhin mengenbezogene Daten gescannter Produkte und generischer Zutaten.",
  },
  el:{
    officialNutrition:"Επίσημα διατροφικά στοιχεία SEB",
    officialPer100g:"Ανά 100 g",
    officialNutritionHelp:"Οι επίσημες τιμές ανά 100 g παραμένουν ξεχωριστές από τα σύνολα του γεύματος. Τα σύνολα συνεχίζουν να χρησιμοποιούν δεδομένα ποσότητας από σαρωμένα προϊόντα και γενικά υλικά.",
  },
};

class Cook4MeRecipeHubPanelV42 extends BasePanel{
  constructor(){
    super();
    this._nutritionAutoFillEntry="";
    this._nutritionAutoFillBusy=false;
    this._nutritionAutoFillResult=null;
  }

  _t(key){return TEXT[this._langCode()]?.[key]||TEXT.en[key]||super._t(key);}

  _renderTab(){
    const result=super._renderTab();
    queueMicrotask(()=>void this._maybeAutoFillNutritionCatalog());
    return result;
  }

  async _maybeAutoFillNutritionCatalog(){
    const entryId=String(this._entryId||"");
    if(!entryId||this._nutritionAutoFillBusy||this._nutritionAutoFillEntry===entryId)return;
    this._nutritionAutoFillEntry=entryId;
    this._nutritionAutoFillBusy=true;
    try{
      const settings=await this._api("cook4me/v16/nutrition_settings",{entry_id:entryId});
      const custom=Boolean(settings?.fdcApiKeyConfigured);
      const fill=await this._api("cook4me/v16/nutrition_catalog_fill",{
        entry_id:entryId,
        limit:custom?25:3,
      });
      this._nutritionAutoFillResult=fill||null;
      if(fill){
        this._nutritionSettings={
          ...(this._nutritionSettings||{}),
          ...settings,
          catalogCount:fill.catalogCount??settings?.catalogCount??this._nutritionSettings?.catalogCount,
          catalogTotal:fill.catalogTotal??this._nutritionSettings?.catalogTotal,
          remaining:fill.remaining??this._nutritionSettings?.remaining,
        };
      }
    }catch(_e){
      // Nutrition enrichment is opportunistic and must never block Recipe Hub.
      this._nutritionAutoFillResult={error:true};
    }finally{
      this._nutritionAutoFillBusy=false;
    }
  }

  _nutritionRecipePayload(recipe){
    const payload=super._nutritionRecipePayload(recipe);
    if(recipe?.officialNutrition&&typeof recipe.officialNutrition==="object"){
      payload.officialNutrition=recipe.officialNutrition;
    }
    return payload;
  }

  _officialUnitLabel(unit){
    if(!unit||typeof unit!=="object")return"";
    const friendly=String(unit.abbreviation||unit.symbol||unit.name||"").trim();
    if(friendly&&!/^UNIT_\d+$/i.test(friendly))return friendly;
    return"";
  }

  _officialNutritionRows(recipe){
    const official=recipe?.officialNutrition;
    if(!official||typeof official!=="object")return[];
    const rows=[];
    for(const row of official.hierarchicalNutrients||[]){
      const value=Number(row?.valuePer100g);
      const name=String(row?.name||row?.path?.at?.(-1)||"").trim();
      if(!Number.isFinite(value)||!name)continue;
      rows.push({name,value,unit:this._officialUnitLabel(row.unit)});
    }
    return rows;
  }

  _officialNutritionBlock(recipe){
    const rows=this._officialNutritionRows(recipe);
    if(!rows.length)return"";
    const chips=rows.map(row=>{
      const shown=Number.isInteger(row.value)?String(row.value):String(Number(row.value.toFixed(2)));
      return `<span class="chip">${this._escape(row.name)}: ${this._escape(shown)}${row.unit?` ${this._escape(row.unit)}`:""}</span>`;
    }).join("");
    return `<section class="card" data-cook4me-official-nutrition style="margin:12px 0">
      <h3 style="margin-top:0">${this._escape(this._t("officialNutrition"))}</h3>
      <div class="muted" style="margin-bottom:7px">${this._escape(this._t("officialPer100g"))} · ${this._escape(this._t("officialNutritionHelp"))}</div>
      <div class="chips">${chips}</div>
    </section>`;
  }

  _detailHtml(recipe){
    let html=super._detailHtml(recipe);
    const block=this._officialNutritionBlock(recipe);
    if(!block||html.includes("data-cook4me-official-nutrition"))return html;
    const marker='<div class="detail-layout"';
    const pos=html.indexOf(marker);
    return pos>=0?`${html.slice(0,pos)}${block}${html.slice(pos)}`:`${block}${html}`;
  }
}

customElements.define("cook4me-recipe-hub-panel-v42",Cook4MeRecipeHubPanelV42);

})();

// cook4me-panel-v43.js
(() => {

const BasePanel=customElements.get("cook4me-recipe-hub-panel-v42");

const TEXT={
  en:{
    officialEnergy:"Energy",
    officialEnergyUnknownUnit:"SEB proves this value is per 100 g, but this payload does not expose the energy unit.",
    cachedUnresolved:"temporarily cached unresolved",
    readyToTry:"ready to try",
  },
  de:{
    officialEnergy:"Energie",
    officialEnergyUnknownUnit:"SEB bestätigt den Bezug pro 100 g, aber diese Antwort enthält keine Einheit für den Energiewert.",
    cachedUnresolved:"vorübergehend als ungelöst zwischengespeichert",
    readyToTry:"für einen neuen Versuch bereit",
  },
  el:{
    officialEnergy:"Ενέργεια",
    officialEnergyUnknownUnit:"Η SEB επιβεβαιώνει ότι η τιμή είναι ανά 100 g, αλλά αυτό το payload δεν εκθέτει τη μονάδα ενέργειας.",
    cachedUnresolved:"προσωρινά αποθηκευμένα ως μη επιλυμένα",
    readyToTry:"έτοιμα για νέα προσπάθεια",
  },
};

class Cook4MeRecipeHubPanelV43 extends BasePanel{
  _t(key){return TEXT[this._langCode()]?.[key]||TEXT.en[key]||super._t(key);}

  async _maybeAutoFillNutritionCatalog(){
    const entryId=String(this._entryId||"");
    if(!entryId||this._nutritionAutoFillBusy||this._nutritionAutoFillEntry===entryId)return;
    this._nutritionAutoFillEntry=entryId;
    this._nutritionAutoFillBusy=true;
    try{
      const settings=await this._api("cook4me/v16/nutrition_settings",{entry_id:entryId});
      this._nutritionSettings={...(this._nutritionSettings||{}),...(settings||{})};
      if(Number(settings?.remaining)===0){
        this._nutritionAutoFillResult={skipped:true,reason:"catalog_complete",...settings};
        return;
      }
      const custom=Boolean(settings?.fdcApiKeyConfigured);
      const fill=await this._api("cook4me/v16/nutrition_catalog_fill",{
        entry_id:entryId,
        limit:custom?25:3,
      });
      this._nutritionAutoFillResult=fill||null;
      if(fill)this._nutritionSettings={...(this._nutritionSettings||{}),...fill};
    }catch(_e){
      this._nutritionAutoFillResult={error:true};
    }finally{
      this._nutritionAutoFillBusy=false;
    }
  }

  _officialNutritionBlock(recipe){
    const official=recipe?.officialNutrition;
    if(!official||typeof official!=="object")return"";
    const rows=super._officialNutritionRows(recipe);
    const energy=Number(official.energyPer100gValue);
    if(!rows.length&&!Number.isFinite(energy))return"";

    const chips=[];
    if(Number.isFinite(energy)){
      const shown=Number.isInteger(energy)?String(energy):String(Number(energy.toFixed(2)));
      chips.push(`<span class="chip">${this._escape(this._t("officialEnergy"))}: ${this._escape(shown)}</span>`);
    }
    for(const row of rows){
      const shown=Number.isInteger(row.value)?String(row.value):String(Number(row.value.toFixed(2)));
      chips.push(`<span class="chip">${this._escape(row.name)}: ${this._escape(shown)}${row.unit?` ${this._escape(row.unit)}`:""}</span>`);
    }

    return `<section class="card" data-cook4me-official-nutrition style="margin:12px 0">
      <h3 style="margin-top:0">${this._escape(this._t("officialNutrition"))}</h3>
      <div class="muted" style="margin-bottom:7px">${this._escape(this._t("officialPer100g"))} · ${this._escape(this._t("officialNutritionHelp"))}</div>
      <div class="chips">${chips.join("")}</div>
      ${Number.isFinite(energy)?`<div class="muted" style="margin-top:7px">${this._escape(this._t("officialEnergyUnknownUnit"))}</div>`:""}
    </section>`;
  }

  _nutritionSettingsHtml(){
    const html=super._nutritionSettingsHtml();
    const s=this._nutritionSettings||{};
    const blocked=Number(s.blockedFailures||0);
    const actionable=Number(s.actionableRemaining||0);
    const parts=[];
    if(blocked>0)parts.push(`${blocked} ${this._t("cachedUnresolved")}`);
    if(Number.isFinite(actionable)&&Number.isFinite(Number(s.remaining)))parts.push(`${actionable} ${this._t("readyToTry")}`);
    if(!parts.length)return html;
    const extra=`<div data-nutrition-resolution-status class="muted" style="margin-top:5px">${this._escape(parts.join(" · "))}</div>`;
    const pos=html.lastIndexOf("</section>");
    return pos>=0?`${html.slice(0,pos)}${extra}${html.slice(pos)}`:`${html}${extra}`;
  }

  _bindNutritionSettings(c){
    c.querySelector("#saveFdcApiKey")?.addEventListener("click",async()=>{
      const key=String(c.querySelector("#fdcApiKey")?.value||"").trim();
      if(!key)return;
      try{
        this._nutritionSettings=await this._api("cook4me/v16/nutrition_settings_set",{entry_id:this._entryId,api_key:key});
        this._nutritionAutoFillEntry="";
        await this._maybeAutoFillNutritionCatalog();
        this._renderTab();
      }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
    });
    c.querySelector("#clearFdcApiKey")?.addEventListener("click",async()=>{
      try{
        this._nutritionSettings=await this._api("cook4me/v16/nutrition_settings_set",{entry_id:this._entryId,api_key:""});
        this._nutritionAutoFillEntry="";
        await this._maybeAutoFillNutritionCatalog();
        this._renderTab();
      }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
    });
    c.querySelector("#buildNutritionCatalog")?.addEventListener("click",async()=>{
      const button=c.querySelector("#buildNutritionCatalog");if(button)button.disabled=true;
      try{
        const custom=Boolean(this._nutritionSettings?.fdcApiKeyConfigured);
        const result=await this._api("cook4me/v16/nutrition_catalog_fill",{entry_id:this._entryId,limit:custom?25:3});
        this._nutritionSettings={...(this._nutritionSettings||{}),...result};
        this._nutritionAutoFillResult=result;
        this._renderTab();
      }catch(e){this._message(`${this._t("error")}: ${e.message||e}`,true);}
      finally{if(button)button.disabled=false;}
    });
  }
}

customElements.define("cook4me-recipe-hub-panel-v43",Cook4MeRecipeHubPanelV43);

})();

